const fs=require('fs'),path=require('path'),{execSync}=require('child_process');
const files={"frontend/src/app/dashboard/settings/page.tsx":"\"use client\";\nimport { useState } from \"react\";\nimport { motion } from \"framer-motion\";\nimport { useTheme, useToast, useConfirm } from \"../../../components/layout/DashboardLayout\";\nimport { useAuthStore } from \"../../../store/auth.store\";\nimport { api } from \"../../../lib/api\";\nimport toast from \"react-hot-toast\";\nimport { User, Bell, Shield, Palette, Globe, Trash2, Eye, EyeOff, ChevronRight, Camera, Sun, Moon, Check, CreditCard } from \"lucide-react\";\n\nconst V = { v500: \"#6B35E8\", v400: \"#8B5CF6\", v300: \"#A78BFA\" };\nconst T = {\n  dark:  { card: \"#181230\", border: \"rgba(255,255,255,0.06)\", text: \"#fff\", muted: \"rgba(255,255,255,0.38)\", faint: \"rgba(255,255,255,0.04)\", input: \"rgba(255,255,255,0.05)\" },\n  light: { card: \"#fff\",    border: \"rgba(15,5,32,0.07)\",    text: \"#0D0918\", muted: \"rgba(13,9,24,0.45)\", faint: \"rgba(15,5,32,0.03)\", input: \"rgba(15,5,32,0.04)\" },\n};\n\nconst SECTIONS = [\n  { id: \"profile\",       label: \"Profile\",      icon: User    },\n  { id: \"notifications\", label: \"Alerts\",       icon: Bell    },\n  { id: \"security\",      label: \"Security\",     icon: Shield  },\n  { id: \"appearance\",    label: \"Appearance\",   icon: Palette },\n  { id: \"domain\",        label: \"Domain\",        icon: Globe   },\n  { id: \"payments\",      label: \"Payments\",     icon: CreditCard },\n  { id: \"danger\",        label: \"Danger Zone\",  icon: Trash2  },\n];\n\nfunction SettingRow({ label, desc, children, t }: any) {\n  return (\n    <div className=\"flex items-center justify-between py-4 gap-4\" style={{ borderBottom: `1px solid ${t.border}` }}>\n      <div className=\"flex-1 min-w-0\">\n        <p className=\"text-sm font-semibold\" style={{ color: t.text }}>{label}</p>\n        {desc && <p className=\"text-xs mt-0.5\" style={{ color: t.muted }}>{desc}</p>}\n      </div>\n      <div className=\"flex-shrink-0\">{children}</div>\n    </div>\n  );\n}\n\nfunction Toggle({ value, onChange }: { value: boolean; onChange: (v: boolean) => void }) {\n  return (\n    <button onClick={() => onChange(!value)}\n      className=\"relative flex-shrink-0 transition-all\"\n      style={{ width: 44, height: 24, borderRadius: 12, border: \"none\", cursor: \"pointer\", background: value ? V.v500 : \"rgba(128,128,128,0.2)\" }}>\n      <div className=\"absolute top-0.5 w-5 h-5 rounded-full bg-white transition-all shadow-sm\" style={{ left: value ? 22 : 2 }} />\n    </button>\n  );\n}\n\nfunction TextInput({ label, value, onChange, type = \"text\", placeholder, t, disabled }: any) {\n  const [show, setShow] = useState(false);\n  return (\n    <div>\n      <label className=\"block text-xs font-semibold mb-1.5\" style={{ color: t.muted }}>{label}</label>\n      <div className=\"relative\">\n        <input\n          type={type === \"password\" ? (show ? \"text\" : \"password\") : type}\n          value={value} onChange={e => onChange(e.target.value)}\n          placeholder={placeholder} disabled={disabled}\n          className=\"w-full px-4 py-3 rounded-xl text-sm outline-none\"\n          style={{ border: `1px solid ${t.border}`, background: disabled ? t.faint : t.input, color: t.text, fontFamily: \"inherit\", paddingRight: type === \"password\" ? 44 : 16, opacity: disabled ? 0.6 : 1 }}\n        />\n        {type === \"password\" && (\n          <button type=\"button\" onClick={() => setShow(!show)} className=\"absolute right-3 top-1/2 -translate-y-1/2\" style={{ border: \"none\", background: \"none\", cursor: \"pointer\", color: t.muted }}>\n            {show ? <EyeOff size={14} /> : <Eye size={14} />}\n          </button>\n        )}\n      </div>\n    </div>\n  );\n}\n\n\nfunction DomainSection({ t, storeId }: { t: any; storeId?: string }) {\n  const [domain, setDomain] = useState(\"\");\n  const [saving, setSaving] = useState(false);\n  const [verified, setVerified] = useState(false);\n\n  const save = async () => {\n    if (!domain.trim()) return;\n    setSaving(true);\n    try {\n      const { api } = await import(\"../../../lib/api\");\n      await api.put(`/stores/${storeId}/custom-domain`, { domain: domain.trim().toLowerCase() });\n      setVerified(true);\n      toast.success(\"Domain saved! Now add the CNAME record below to your DNS.\");\n    } catch {\n      toast.error(\"Backend offline — save your domain when Render is live\");\n    } finally { setSaving(false); }\n  };\n\n  return (\n    <div className=\"space-y-4\">\n      <div>\n        <label className=\"block text-xs font-semibold mb-2\" style={{ color: t.muted }}>Custom domain</label>\n        <div className=\"flex gap-2\">\n          <input value={domain} onChange={e => setDomain(e.target.value)} placeholder=\"store.yourbrand.com\"\n            className=\"flex-1 px-4 py-2.5 rounded-xl text-sm outline-none\"\n            style={{ background: t.faint, border: `1px solid ${t.border}`, color: t.text, fontFamily: \"inherit\" }}/>\n          <button onClick={save} disabled={!domain.trim() || saving}\n            className=\"px-4 py-2.5 rounded-xl text-sm font-bold text-white disabled:opacity-50\"\n            style={{ background: \"linear-gradient(135deg,#6B35E8,#3D1C8A)\", border: \"none\", cursor: \"pointer\" }}>\n            {saving ? \"Saving...\" : \"Save\"}\n          </button>\n        </div>\n        <p className=\"text-xs mt-1.5\" style={{ color: t.muted }}>Must be a subdomain you control (e.g. shop.yourbrand.com)</p>\n      </div>\n      {(verified || domain) && (\n        <div className=\"p-4 rounded-xl space-y-2\" style={{ background: \"rgba(107,53,232,0.06)\", border: \"1px solid rgba(107,53,232,0.2)\" }}>\n          <p className=\"text-xs font-bold\" style={{ color: \"#A78BFA\" }}>Add this CNAME record to your DNS:</p>\n          <div className=\"grid grid-cols-2 gap-2 text-xs\">\n            <div><p style={{ color: t.muted, marginBottom: 2 }}>Type</p><p className=\"font-mono font-bold\" style={{ color: t.text }}>CNAME</p></div>\n            <div><p style={{ color: t.muted, marginBottom: 2 }}>Name</p><p className=\"font-mono font-bold\" style={{ color: t.text }}>{domain.split(\".\")[0] || \"store\"}</p></div>\n            <div className=\"col-span-2\"><p style={{ color: t.muted, marginBottom: 2 }}>Value</p><p className=\"font-mono font-bold text-xs\" style={{ color: t.text }}>cname.dropos-dns.com</p></div>\n          </div>\n          <p className=\"text-xs\" style={{ color: t.muted }}>DNS changes take 10-60 minutes to propagate. SSL is automatic.</p>\n        </div>\n      )}\n    </div>\n  );\n}\n\nexport default function SettingsPage() {\n  const { theme, toggle: toggleTheme } = useTheme();\n  const { show } = useToast();\n  const { confirm } = useConfirm();\n  const { user } = useAuthStore();\n  const isDark = theme === \"dark\";\n  const t = isDark ? T.dark : T.light;\n\n  const [activeSection, setActiveSection] = useState(\"profile\");\n  const [saving, setSaving] = useState(false);\n  const [name, setName]   = useState(user?.name || \"\");\n  const [email, setEmail] = useState(user?.email || \"\");\n  const [currentPw, setCurrentPw] = useState(\"\");\n  const [newPw, setNewPw]         = useState(\"\");\n  const [notifs, setNotifs] = useState({ orders: true, marketing: false, security: true, updates: true, kiro: true });\n\n  const handleSaveProfile = async () => {\n    setSaving(true);\n    try { await api.put(\"/auth/profile\", { name, email }); show(\"Profile saved\", \"success\"); }\n    catch { show(\"Saved locally (backend offline)\", \"info\"); }\n    finally { setSaving(false); }\n  };\n\n  const handleChangePassword = async () => {\n    if (!currentPw || !newPw) { show(\"Fill in both fields\", \"error\"); return; }\n    try { await api.put(\"/auth/password\", { currentPassword: currentPw, newPassword: newPw }); show(\"Password updated\", \"success\"); setCurrentPw(\"\"); setNewPw(\"\"); }\n    catch (e: any) { show(e.response?.data?.message || \"Failed\", \"error\"); }\n  };\n\n  const handleDelete = async () => {\n    const ok = await confirm({ title: \"Delete your account?\", message: \"This permanently deletes your account and all store data. Cannot be undone.\", confirmText: \"Yes, delete everything\", cancelText: \"Keep my account\", variant: \"danger\" });\n    if (ok) show(\"Account deletion requested\", \"info\");\n  };\n\n  return (\n    <div className=\"max-w-4xl mx-auto\">\n      <motion.div initial={{ opacity: 0, y: -8 }} animate={{ opacity: 1, y: 0 }} className=\"mb-6\">\n        <h1 className=\"text-xl sm:text-2xl font-black tracking-tight\" style={{ color: t.text }}>Settings</h1>\n        <p className=\"text-xs sm:text-sm mt-1\" style={{ color: t.muted }}>Manage your account and preferences</p>\n      </motion.div>\n\n      <div className=\"flex flex-col sm:flex-row gap-4\">\n        {/* Section sidebar - horizontal scroll on mobile, vertical on desktop */}\n        <div className=\"sm:w-44 flex-shrink-0\">\n          <div className=\"flex sm:flex-col gap-1 overflow-x-auto pb-1 sm:pb-0\" style={{ scrollbarWidth: \"none\" }}>\n            {SECTIONS.map(s => {\n              const Icon = s.icon;\n              const active = activeSection === s.id;\n              return (\n                <button key={s.id} onClick={() => setActiveSection(s.id)}\n                  className=\"flex items-center gap-2.5 px-3 py-2.5 rounded-xl text-left transition-all whitespace-nowrap sm:whitespace-normal flex-shrink-0 sm:flex-shrink w-auto sm:w-full\"\n                  style={{ background: active ? \"rgba(107,53,232,0.1)\" : \"transparent\", border: `1px solid ${active ? \"rgba(107,53,232,0.25)\" : \"transparent\"}`, color: active ? V.v300 : t.muted }}>\n                  <Icon size={14} />\n                  <span className=\"text-xs font-semibold\">{s.label}</span>\n                </button>\n              );\n            })}\n          </div>\n        </div>\n\n        {/* Content */}\n        <div className=\"flex-1 min-w-0\">\n          <motion.div key={activeSection} initial={{ opacity: 0, x: 8 }} animate={{ opacity: 1, x: 0 }} transition={{ duration: 0.15 }}\n            className=\"rounded-2xl p-4 sm:p-6\" style={{ background: t.card, border: `1px solid ${t.border}` }}>\n\n            {activeSection === \"profile\" && (\n              <div className=\"space-y-4\">\n                <h2 className=\"text-sm font-bold mb-4\" style={{ color: t.text }}>Profile</h2>\n                {/* Avatar */}\n                <div className=\"flex items-center gap-4 mb-2\">\n                  <div className=\"relative\">\n                    <div className=\"w-16 h-16 rounded-2xl flex items-center justify-center text-2xl font-black text-white\" style={{ background: \"linear-gradient(135deg,#6B35E8,#3D1C8A)\" }}>\n                      {name?.[0]?.toUpperCase() || \"U\"}\n                    </div>\n                    <button className=\"absolute -bottom-1 -right-1 w-6 h-6 rounded-full flex items-center justify-center text-white\" style={{ background: V.v500 }}>\n                      <Camera size={10} />\n                    </button>\n                  </div>\n                  <div>\n                    <p className=\"text-sm font-semibold\" style={{ color: t.text }}>{name || \"Your Name\"}</p>\n                    <p className=\"text-xs\" style={{ color: t.muted }}>{email}</p>\n                  </div>\n                </div>\n                <TextInput label=\"Full Name\" value={name} onChange={setName} placeholder=\"Your name\" t={t} />\n                <TextInput label=\"Email\" value={email} onChange={setEmail} type=\"email\" placeholder=\"you@example.com\" t={t} />\n                <button onClick={handleSaveProfile} disabled={saving}\n                  className=\"w-full sm:w-auto px-6 py-2.5 rounded-xl text-sm font-bold text-white flex items-center justify-center gap-2 disabled:opacity-60\"\n                  style={{ background: \"linear-gradient(135deg,#6B35E8,#3D1C8A)\" }}>\n                  {saving ? \"Saving...\" : \"Save Profile\"}\n                </button>\n              </div>\n            )}\n\n            {activeSection === \"notifications\" && (\n              <div>\n                <h2 className=\"text-sm font-bold mb-1\" style={{ color: t.text }}>Notification Preferences</h2>\n                <p className=\"text-xs mb-4\" style={{ color: t.muted }}>Choose what you want to be notified about</p>\n                {[\n                  { key: \"orders\",    label: \"New Orders\",          desc: \"Get notified when a customer places an order\" },\n                  { key: \"kiro\",      label: \"KIRO Alerts\",         desc: \"Morning briefs, opportunities, and urgent alerts\" },\n                  { key: \"security\",  label: \"Security Alerts\",     desc: \"Login attempts and account security\" },\n                  { key: \"marketing\", label: \"Marketing Tips\",      desc: \"Product ideas and growth suggestions\" },\n                  { key: \"updates\",   label: \"Platform Updates\",    desc: \"New features and improvements\" },\n                ].map(n => (\n                  <SettingRow key={n.key} label={n.label} desc={n.desc} t={t}>\n                    <Toggle value={notifs[n.key as keyof typeof notifs]} onChange={v => setNotifs(p => ({ ...p, [n.key]: v }))} />\n                  </SettingRow>\n                ))}\n              </div>\n            )}\n\n            {activeSection === \"security\" && (\n              <div className=\"space-y-4\">\n                <h2 className=\"text-sm font-bold mb-4\" style={{ color: t.text }}>Security</h2>\n                <TextInput label=\"Current Password\" value={currentPw} onChange={setCurrentPw} type=\"password\" placeholder=\"••••••••\" t={t} />\n                <TextInput label=\"New Password\" value={newPw} onChange={setNewPw} type=\"password\" placeholder=\"Min 8 characters\" t={t} />\n                <button onClick={handleChangePassword}\n                  className=\"w-full sm:w-auto px-6 py-2.5 rounded-xl text-sm font-bold text-white\"\n                  style={{ background: \"linear-gradient(135deg,#6B35E8,#3D1C8A)\" }}>\n                  Update Password\n                </button>\n                <div className=\"pt-4\" style={{ borderTop: `1px solid ${t.border}` }}>\n                  <SettingRow label=\"Two-Factor Authentication\" desc=\"Add an extra layer of security to your account\" t={t}>\n                    <button className=\"text-xs font-semibold px-3 py-1.5 rounded-lg\" style={{ border: `1px solid ${t.border}`, color: t.muted }}>Enable</button>\n                  </SettingRow>\n                </div>\n              </div>\n            )}\n\n            {activeSection === \"payments\" && (\n              <div className=\"space-y-6\">\n                <h2 className=\"text-sm font-bold\" style={{ color: t.text }}>Payment Settings</h2>\n\n                {/* Paystack */}\n                <div style={{ padding:16, borderRadius:14, background:t.faint, border:`1px solid ${t.border}` }}>\n                  <div style={{ display:\"flex\", alignItems:\"center\", gap:10, marginBottom:14, paddingBottom:12, borderBottom:`1px solid ${t.border}` }}>\n                    <div style={{ width:32, height:32, borderRadius:9, background:\"rgba(245,158,11,0.1)\", display:\"flex\", alignItems:\"center\", justifyContent:\"center\" }}>\n                      <span style={{ fontSize:16 }}>₦</span>\n                    </div>\n                    <div>\n                      <p className=\"text-sm font-bold\" style={{ color:t.text }}>Paystack</p>\n                      <p className=\"text-xs\" style={{ color:t.muted }}>Accept Naira payments — card, bank transfer, USSD</p>\n                    </div>\n                  </div>\n                  <div style={{ display:\"flex\", flexDirection:\"column\", gap:10 }}>\n                    <div>\n                      <label className=\"text-xs font-semibold block mb-1.5\" style={{ color:t.muted }}>Public Key</label>\n                      <input type=\"text\" placeholder=\"pk_live_...\" defaultValue={(user as any)?.stores?.[0]?.paystackPublicKey||\"\"}\n                        style={{ width:\"100%\", padding:\"10px 14px\", borderRadius:10, border:`1px solid ${t.border}`, background:\"rgba(255,255,255,0.04)\", color:t.text, fontSize:13, fontFamily:\"inherit\", outline:\"none\" }}/>\n                    </div>\n                    <div>\n                      <label className=\"text-xs font-semibold block mb-1.5\" style={{ color:t.muted }}>Secret Key</label>\n                      <input type=\"password\" placeholder=\"sk_live_...\" defaultValue={(user as any)?.stores?.[0]?.paystackSecretKey?\"sk_live_••••••••\":\"\"}\n                        style={{ width:\"100%\", padding:\"10px 14px\", borderRadius:10, border:`1px solid ${t.border}`, background:\"rgba(255,255,255,0.04)\", color:t.text, fontSize:13, fontFamily:\"inherit\", outline:\"none\" }}/>\n                    </div>\n                    <p className=\"text-xs\" style={{ color:t.muted }}>\n                      Get your keys from <a href=\"https://dashboard.paystack.com/#/settings/developer\" target=\"_blank\" rel=\"noreferrer\" style={{ color:\"#6B35E8\" }}>Paystack dashboard → Settings → API Keys</a>\n                    </p>\n                  </div>\n                </div>\n\n                {/* WhatsApp */}\n                <div style={{ padding:16, borderRadius:14, background:t.faint, border:`1px solid ${t.border}` }}>\n                  <div style={{ display:\"flex\", alignItems:\"center\", gap:10, marginBottom:14, paddingBottom:12, borderBottom:`1px solid ${t.border}` }}>\n                    <div style={{ width:32, height:32, borderRadius:9, background:\"rgba(37,211,102,0.1)\", display:\"flex\", alignItems:\"center\", justifyContent:\"center\" }}>\n                      <svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"#25D366\"><path d=\"M17.472 14.382c-.297-.149-1.758-.867-2.03-.967-.273-.099-.471-.148-.67.15-.197.297-.767.966-.94 1.164-.173.199-.347.223-.644.075-.297-.15-1.255-.463-2.39-1.475-.883-.788-1.48-1.761-1.653-2.059-.173-.297-.018-.458.13-.606.134-.133.298-.347.446-.52.149-.174.198-.298.298-.497.099-.198.05-.371-.025-.52-.075-.149-.669-1.612-.916-2.207-.242-.579-.487-.5-.669-.51-.173-.008-.371-.01-.57-.01-.198 0-.52.074-.792.372-.272.297-1.04 1.016-1.04 2.479 0 1.462 1.065 2.875 1.213 3.074.149.198 2.096 3.2 5.077 4.487.709.306 1.262.489 1.694.625.712.227 1.36.195 1.871.118.571-.085 1.758-.719 2.006-1.413.248-.694.248-1.289.173-1.413-.074-.124-.272-.198-.57-.347m-5.421 7.403h-.004a9.87 9.87 0 01-5.031-1.378l-.361-.214-3.741.982.998-3.648-.235-.374a9.86 9.86 0 01-1.51-5.26c.001-5.45 4.436-9.884 9.888-9.884 2.64 0 5.122 1.03 6.988 2.898a9.825 9.825 0 012.893 6.994c-.003 5.45-4.437 9.884-9.885 9.884m8.413-18.297A11.815 11.815 0 0012.05 0C5.495 0 .16 5.335.157 11.892c0 2.096.547 4.142 1.588 5.945L.057 24l6.305-1.654a11.882 11.882 0 005.683 1.448h.005c6.554 0 11.89-5.335 11.893-11.893a11.821 11.821 0 00-3.48-8.413z\"/></svg>\n                    </div>\n                    <div>\n                      <p className=\"text-sm font-bold\" style={{ color:t.text }}>WhatsApp Chat</p>\n                      <p className=\"text-xs\" style={{ color:t.muted }}>Show a WhatsApp button on your store for customer messages</p>\n                    </div>\n                  </div>\n                  <div>\n                    <label className=\"text-xs font-semibold block mb-1.5\" style={{ color:t.muted }}>Your WhatsApp Number</label>\n                    <input type=\"tel\" placeholder=\"+2348012345678\"\n                      style={{ width:\"100%\", padding:\"10px 14px\", borderRadius:10, border:`1px solid ${t.border}`, background:\"rgba(255,255,255,0.04)\", color:t.text, fontSize:13, fontFamily:\"inherit\", outline:\"none\" }}/>\n                    <p className=\"text-xs mt-1.5\" style={{ color:t.muted }}>Include country code. Customers will tap to start a WhatsApp conversation.</p>\n                  </div>\n                </div>\n\n                <button className=\"px-6 py-2.5 rounded-xl text-sm font-bold text-white\" style={{ background:\"linear-gradient(135deg,#6B35E8,#3D1C8A)\" }}>\n                  Save payment settings\n                </button>\n              </div>\n            )}\n\n            {activeSection === \"appearance\" && (\n              <div>\n                <h2 className=\"text-sm font-bold mb-4\" style={{ color: t.text }}>Appearance</h2>\n                <SettingRow label=\"Theme\" desc=\"Choose how the dashboard looks\" t={t}>\n                  <div className=\"flex gap-2\">\n                    {[{ mode: \"dark\", icon: Moon, label: \"Dark\" }, { mode: \"light\", icon: Sun, label: \"Light\" }].map(opt => {\n                      const Icon = opt.icon;\n                      const active = theme === opt.mode;\n                      return (\n                        <button key={opt.mode} onClick={toggleTheme}\n                          className=\"flex items-center gap-1.5 px-3 py-2 rounded-xl text-xs font-semibold transition-all\"\n                          style={{ background: active ? V.v500 : t.faint, color: active ? \"#fff\" : t.muted, border: `1px solid ${active ? V.v500 : t.border}` }}>\n                          <Icon size={12} /> {opt.label}\n                          {active && <Check size={11} />}\n                        </button>\n                      );\n                    })}\n                  </div>\n                </SettingRow>\n              </div>\n            )}\n\n      \n      {activeSection === \"domain\" && (\n        <div className=\"space-y-0\" style={{ borderRadius: 16, overflow: \"hidden\", border: `1px solid ${t.border}` }}>\n          <div className=\"p-5\" style={{ borderBottom: `1px solid ${t.border}` }}>\n            <h2 className=\"font-bold text-sm mb-1\" style={{ color: t.text }}>Custom Domain</h2>\n            <p className=\"text-xs\" style={{ color: t.muted }}>Connect your own domain instead of the dropos.io subdomain</p>\n          </div>\n          <div className=\"p-5 space-y-4\">\n            <div>\n              <label className=\"block text-xs font-semibold mb-2\" style={{ color: t.muted }}>Your subdomain (always free)</label>\n              <div className=\"flex items-center gap-2 px-4 py-2.5 rounded-xl\" style={{ background: t.faint, border: `1px solid ${t.border}` }}>\n                <span className=\"text-sm font-semibold\" style={{ color: t.text }}>{user?.stores?.[0]?.slug || \"yourstore\"}</span>\n                <span className=\"text-sm\" style={{ color: t.muted }}>.droposhq.com</span>\n              </div>\n            </div>\n            <DomainSection t={t} storeId={user?.stores?.[0]?.id} />\n          </div>\n        </div>\n      )}\n\n      {activeSection === \"danger\" && (\n              <div>\n                <h2 className=\"text-sm font-bold mb-1 text-red-400\">Danger Zone</h2>\n                <p className=\"text-xs mb-6\" style={{ color: t.muted }}>These actions cannot be undone. Be very careful.</p>\n                <div className=\"p-4 rounded-2xl\" style={{ border: \"1px solid rgba(239,68,68,0.25)\", background: \"rgba(239,68,68,0.05)\" }}>\n                  <p className=\"text-sm font-semibold text-red-400 mb-1\">Delete Account</p>\n                  <p className=\"text-xs mb-4\" style={{ color: t.muted }}>Permanently delete your account and all store data including products, orders, and customer information.</p>\n                  <button onClick={handleDelete} className=\"px-4 py-2 rounded-xl text-xs font-bold text-white\" style={{ background: \"#EF4444\" }}>\n                    Delete My Account\n                  </button>\n                </div>\n              </div>\n            )}\n\n          </motion.div>\n        </div>\n      </div>\n    </div>\n  );\n}\n","frontend/src/app/dashboard/page.tsx":"\"use client\";\nimport { useState, useEffect } from \"react\";\nimport { useQuery } from \"@tanstack/react-query\";\nimport { motion } from \"framer-motion\";\nimport Link from \"next/link\";\n// currency formatting handled inline\nimport {\n  TrendingUp, ShoppingCart, Users, Package, Zap,\n  ChevronRight, Store, Flame, Activity, ArrowUpRight,\n  AlertCircle, Clock, CheckCircle2, RefreshCw\n} from \"lucide-react\";\nimport { useTheme } from \"../../components/layout/DashboardLayout\";\nimport { useAuthStore } from \"../../store/auth.store\";\nimport { api } from \"../../lib/api\";\nimport { OpportunityFeed } from \"../../components/kai/OpportunityFeed\";\nimport { OnboardingTips } from \"../../components/dashboard/OnboardingTips\";\n\nconst V = { v500: \"#6B35E8\", v400: \"#8B5CF6\", v300: \"#A78BFA\", cyan: \"#06B6D4\", green: \"#10B981\", amber: \"#F59E0B\", red: \"#EF4444\" };\n\nconst fmt = (n: number) => new Intl.NumberFormat(\"en-NG\", { style:\"currency\", currency:\"NGN\", maximumFractionDigits:0 }).format(n||0);\n\nfunction StatCard({ label, value, delta, color, icon: Icon, delay = 0 }: any) {\n  const { theme } = useTheme();\n  const isDark = theme === \"dark\";\n  const t = { card: isDark ? \"#181230\" : \"#fff\", border: isDark ? \"rgba(255,255,255,0.06)\" : \"rgba(15,5,32,0.07)\", text: isDark ? \"#fff\" : \"#0D0918\", muted: isDark ? \"rgba(255,255,255,0.38)\" : \"rgba(13,9,24,0.45)\" };\n  return (\n    <motion.div initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} transition={{ delay }}\n      style={{ padding: 18, borderRadius: 16, background: t.card, border: `1px solid ${t.border}` }}>\n      <div style={{ display: \"flex\", alignItems: \"center\", justifyContent: \"space-between\", marginBottom: 12 }}>\n        <div style={{ width: 36, height: 36, borderRadius: 10, display: \"flex\", alignItems: \"center\", justifyContent: \"center\", background: `${color}18` }}>\n          <Icon size={16} color={color} />\n        </div>\n        {delta !== undefined && (\n          <span style={{ fontSize: 11, fontWeight: 700, color: delta >= 0 ? V.green : V.red, background: delta >= 0 ? \"rgba(16,185,129,0.1)\" : \"rgba(239,68,68,0.1)\", padding: \"3px 8px\", borderRadius: 99 }}>\n            {delta >= 0 ? \"+\" : \"\"}{delta}%\n          </span>\n        )}\n      </div>\n      <p style={{ fontSize: 22, fontWeight: 900, color: t.text, letterSpacing: \"-0.04em\", lineHeight: 1 }}>{value}</p>\n      <p style={{ fontSize: 12, color: t.muted, marginTop: 4 }}>{label}</p>\n    </motion.div>\n  );\n}\n\nfunction OrderRow({ order, t }: any) {\n  const statusColors: Record<string, string> = {\n    PENDING: V.amber, COMPLETED: V.green, SHIPPED: V.cyan,\n    DELIVERED: V.v400, CANCELLED: V.red, PROCESSING: V.cyan,\n  };\n  const color = statusColors[order.status] || V.amber;\n  return (\n    <div style={{ display: \"flex\", alignItems: \"center\", gap: 12, padding: \"10px 0\", borderBottom: `1px solid ${t.border}` }}>\n      <div style={{ width: 32, height: 32, borderRadius: 8, background: `${color}15`, display: \"flex\", alignItems: \"center\", justifyContent: \"center\", flexShrink: 0 }}>\n        <ShoppingCart size={13} color={color} />\n      </div>\n      <div style={{ flex: 1, minWidth: 0 }}>\n        <p style={{ fontSize: 13, fontWeight: 600, color: t.text, whiteSpace: \"nowrap\", overflow: \"hidden\", textOverflow: \"ellipsis\" }}>\n          {order.customerName || \"Customer\"}\n        </p>\n        <p style={{ fontSize: 11, color: t.muted, marginTop: 1 }}>#{order.orderNumber || order.id?.slice(-6)}</p>\n      </div>\n      <div style={{ textAlign: \"right\", flexShrink: 0 }}>\n        <p style={{ fontSize: 13, fontWeight: 700, color: t.text }}>{fmt(order.total)}</p>\n        <span style={{ fontSize: 10, fontWeight: 700, color, background: `${color}15`, padding: \"2px 6px\", borderRadius: 99 }}>\n          {order.status}\n        </span>\n      </div>\n    </div>\n  );\n}\n\nexport default function DashboardPage() {\n  const { theme } = useTheme();\n  const { user } = useAuthStore();\n  const isDark = theme === \"dark\";\n  const [greeting, setGreeting] = useState(\"morning\");\n  const storeCurrency = (user?.stores?.[0] as any)?.currency || \"NGN\";\n  const fmtCurrency = (n: number) => {\n    const symbol = storeCurrency === \"NGN\" ? \"₦\" : storeCurrency === \"GBP\" ? \"£\" : storeCurrency === \"USD\" ? \"$\" : \"₦\";\n    return `${symbol}${(n || 0).toLocaleString(\"en-NG\", { maximumFractionDigits: 0 })}`;\n  };\n  const firstName = user?.name?.split(\" \")[0] || user?.email?.split(\"@\")[0] || \"there\";\n  const storeId = user?.stores?.[0]?.id;\n  const storeSlug = user?.stores?.[0]?.slug;\n\n  // No store yet — first-time user\n  if (user && (!user.stores || user.stores.length === 0)) {\n    return (\n      <div style={{ maxWidth:560, margin:\"80px auto 0\", textAlign:\"center\", padding:\"0 24px\" }}>\n        <div style={{ width:72, height:72, borderRadius:20, background:\"linear-gradient(145deg,#2D1B69,#0D0625)\", display:\"flex\", alignItems:\"center\", justifyContent:\"center\", margin:\"0 auto 20px\", boxShadow:\"0 8px 32px rgba(45,27,105,0.25)\" }}>\n          <svg width=\"28\" height=\"28\" viewBox=\"0 0 24 24\" fill=\"none\"><path d=\"M13 2L3 14h9l-1 8 10-12h-9z\" fill=\"white\"/></svg>\n        </div>\n        <h1 style={{ fontSize:26, fontWeight:900, color:isDark?\"#F0ECFF\":\"#130D2E\", margin:\"0 0 10px\", letterSpacing:\"-0.04em\" }}>\n          Welcome, {firstName}!\n        </h1>\n        <p style={{ fontSize:15, color:isDark?\"rgba(240,236,255,0.5)\":\"rgba(19,13,46,0.5)\", margin:\"0 0 32px\", lineHeight:1.6 }}>\n          Your store is being set up. This usually takes a few seconds. Refresh the page to see your dashboard.\n        </p>\n        <a href=\"/dashboard/stores\" style={{ display:\"inline-flex\", alignItems:\"center\", gap:8, padding:\"13px 28px\", borderRadius:12, background:\"#6B35E8\", color:\"#fff\", textDecoration:\"none\", fontSize:14, fontWeight:700 }}>\n          Go to my store →\n        </a>\n      </div>\n    );\n  }\n\n  useEffect(() => {\n    const h = new Date().getHours();\n    setGreeting(h < 12 ? \"morning\" : h < 17 ? \"afternoon\" : \"evening\");\n  }, []);\n\n  const t = {\n    card:   isDark ? \"#181230\" : \"#fff\",\n    border: isDark ? \"rgba(255,255,255,0.06)\" : \"rgba(15,5,32,0.07)\",\n    text:   isDark ? \"#fff\"    : \"#0D0918\",\n    muted:  isDark ? \"rgba(255,255,255,0.38)\" : \"rgba(13,9,24,0.45)\",\n    faint:  isDark ? \"rgba(255,255,255,0.03)\" : \"rgba(15,5,32,0.02)\",\n  };\n\n  const { data: analytics } = useQuery({\n    queryKey: [\"dashboard-analytics\", storeId],\n    queryFn:  () => api.get(`/analytics/${storeId}?period=7`).then(r => r.data.data),\n    enabled:  !!storeId,\n    staleTime: 60000,\n  });\n\n  const { data: recentOrders } = useQuery({\n    queryKey: [\"dashboard-orders\", storeId],\n    queryFn:  () => api.get(`/orders/${storeId}?limit=5`).then(r => r.data.data?.orders || r.data.data || []),\n    enabled:  !!storeId,\n    staleTime: 30000,\n  });\n\n  // Direct product count — more reliable than analytics which may be cached\n  const { data: productCount } = useQuery({\n    queryKey: [\"dashboard-product-count\", storeId],\n    queryFn:  () => api.get(`/products/${storeId}?limit=1`).then(r => {\n      const d = r.data;\n      return d.data?.pagination?.total || d.pagination?.total || d.data?.total || d.total ||\n             (Array.isArray(d.data?.products) ? d.data.products.length : 0) ||\n             (Array.isArray(d.data) ? d.data.length : 0) || 0;\n    }),\n    enabled:  !!storeId,\n    staleTime: 60000,\n  });\n\n  const { data: pulse } = useQuery({\n    queryKey: [\"kiro-pulse\", storeId],\n    queryFn:  () => api.get(`/kai/pulse?storeId=${storeId}&limit=3`).then(r => r.data.data || []),\n    enabled:  !!storeId,\n    staleTime: 120000,\n  });\n\n  const stats = analytics?.summary || analytics?.stats || {};\n  const orders = Array.isArray(recentOrders) ? recentOrders : [];\n  // Deduplicate by type — keep most recent of each type, max 4\n  const seen = new Set<string>();\n  const alerts = (Array.isArray(pulse) ? pulse : [])\n    .filter((a: any) => { if (seen.has(a.type)) return false; seen.add(a.type); return true; })\n    .slice(0, 4);\n\n  const statCards = [\n    { label: \"Revenue (7d)\",  value: fmtCurrency(stats.revenue || 0),        delta: stats.revenueDelta,  color: V.v400,  icon: TrendingUp  },\n    { label: \"Orders (7d)\",   value: (stats.orders    || 0).toLocaleString(), delta: stats.ordersDelta,   color: V.cyan,  icon: ShoppingCart },\n    { label: \"Customers\",     value: (stats.customers || 0).toLocaleString(), delta: undefined,            color: V.green, icon: Users        },\n    { label: \"Products\",      value: (productCount || stats.products || analytics?.totalProducts || 0).toLocaleString(), delta: undefined, color: V.amber, icon: Package },\n  ];\n\n  const quickActions = [\n    { label: \"Add Product\",  href: \"/dashboard/products\",   icon: Package,   color: V.v400  },\n    { label: \"View Store\",   href: storeSlug ? `/store/${storeSlug}` : \"/dashboard/stores\", icon: Store, color: V.cyan, target: \"_blank\" },\n    { label: \"Flash Sale\",   href: \"/dashboard/flash-sales\",icon: Flame,     color: V.amber },\n    { label: \"Analytics\",    href: \"/dashboard/analytics\",  icon: Activity,  color: V.green },\n  ];\n\n  return (\n    <div style={{ maxWidth: 1200, margin: \"0 auto\" }}>\n      {/* Header */}\n      <motion.div initial={{ opacity: 0, y: -8 }} animate={{ opacity: 1, y: 0 }} style={{ marginBottom: 24 }}>\n        <h1 style={{ fontSize: 22, fontWeight: 900, letterSpacing: \"-0.04em\", color: t.text, marginBottom: 4 }}>\n          Good {greeting}, {firstName} 👋\n        </h1>\n        <p style={{ fontSize: 13, color: t.muted }}>\n          {user?.stores?.[0]?.name || \"Your store\"} · {new Date().toLocaleDateString(\"en-NG\", { weekday: \"long\", day: \"numeric\", month: \"long\" })}\n        </p>\n      </motion.div>\n\n      {/* Stats */}\n      <div style={{ display: \"grid\", gridTemplateColumns: \"repeat(4,1fr)\", gap: 12, marginBottom: 20 }} className=\"grid-cols-2 sm:grid-cols-4\">\n        {statCards.map((s, i) => <StatCard key={s.label} {...s} delay={i * 0.07} />)}\n      </div>\n\n      <div style={{ display: \"grid\", gridTemplateColumns: \"1fr 340px\", gap: 16 }} className=\"grid-1col lg:grid-2col\">\n        {/* Left: Recent Orders */}\n        <div>\n          <motion.div initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.3 }}\n            style={{ padding: 18, borderRadius: 16, background: t.card, border: `1px solid ${t.border}`, marginBottom: 16 }}>\n            <div style={{ display: \"flex\", alignItems: \"center\", justifyContent: \"space-between\", marginBottom: 14 }}>\n              <span style={{ fontSize: 13, fontWeight: 700, color: t.text }}>Recent Orders</span>\n              <Link href=\"/dashboard/orders\" style={{ display: \"flex\", alignItems: \"center\", gap: 4, fontSize: 12, color: V.v400, textDecoration: \"none\", fontWeight: 600 }}>\n                View all <ChevronRight size={13} />\n              </Link>\n            </div>\n            {orders.length === 0 ? (\n              <div style={{ textAlign: \"center\", padding: \"28px 0\" }}>\n                <ShoppingCart size={28} style={{ color: t.muted, margin: \"0 auto 8px\" }} />\n                <p style={{ fontSize: 12, color: t.muted }}>No orders yet. Share your store link to get your first sale.</p>\n                {storeSlug && (\n                  <a href={`/store/${storeSlug}`} target=\"_blank\" rel=\"noreferrer\"\n                    style={{ display: \"inline-flex\", alignItems: \"center\", gap: 6, marginTop: 12, fontSize: 12, fontWeight: 700, color: V.v400, textDecoration: \"none\", background: \"rgba(107,53,232,0.08)\", padding: \"6px 14px\", borderRadius: 99, border: \"1px solid rgba(107,53,232,0.2)\" }}>\n                    <Store size={11} /> View your store <ArrowUpRight size={11} />\n                  </a>\n                )}\n              </div>\n            ) : (\n              <div>\n                {orders.slice(0, 5).map((o: any) => <OrderRow key={o.id} order={o} t={t} />)}\n              </div>\n            )}\n          </motion.div>\n\n          {/* Onboarding tips for new users */}\n          {storeId && (\n            <OnboardingTips\n              isDark={isDark}\n              storeSlug={storeSlug || \"\"}\n              completedSteps={[\n                ...(user?.stores?.[0]?.id ? [\"store\"] : []),\n                ...((productCount || 0) > 0 ? [\"product\"] : []),\n                ...(orders.length > 0 ? [\"kiro\"] : []),\n                ...(!!(user?.stores?.[0] as any)?.paystackPublicKey || !!(user?.stores?.[0] as any)?.stripeAccountId ? [\"payment\"] : []),\n              ]}\n            />\n          )}\n\n          {/* KIRO Opportunity Feed - proactive intelligence */}\n          {storeId && <OpportunityFeed storeId={storeId} isDark={isDark} onAction={(action) => {\n            // Trigger KIRO chat with the action\n            if (typeof window !== \"undefined\") {\n              window.dispatchEvent(new CustomEvent(\"kiro:execute\", { detail: { prompt: action } }));\n            }\n          }}/>}\n\n          {/* KIRO Pulse Alerts */}\n          {alerts.length > 0 && (\n            <motion.div initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.4 }}\n              style={{ padding: 18, borderRadius: 16, background: t.card, border: `1px solid ${t.border}` }}>\n              <div style={{ display: \"flex\", alignItems: \"center\", gap: 8, marginBottom: 14 }}>\n                <Zap size={14} color={V.v400} />\n                <span style={{ fontSize: 13, fontWeight: 700, color: t.text }}>KIRO Alerts</span>\n              </div>\n              <div style={{ display: \"flex\", flexDirection: \"column\", gap: 8 }}>\n                {alerts.map((a: any) => (\n                  <div key={a.id} style={{ display: \"flex\", gap: 10, padding: 10, borderRadius: 10, background: t.faint, border: `1px solid ${t.border}` }}>\n                    <AlertCircle size={13} color={a.severity === \"high\" ? V.red : V.amber} style={{ flexShrink: 0, marginTop: 1 }} />\n                    <div>\n                      <p style={{ fontSize: 12, fontWeight: 600, color: t.text }}>{a.title}</p>\n                      <p style={{ fontSize: 11, color: t.muted, marginTop: 2 }}>{a.message}</p>\n                    </div>\n                  </div>\n                ))}\n              </div>\n            </motion.div>\n          )}\n        </div>\n\n        {/* Right column */}\n        <div style={{ display: \"flex\", flexDirection: \"column\", gap: 14 }}>\n          {/* KIRO CTA */}\n          <motion.div initial={{ opacity: 0, x: 16 }} animate={{ opacity: 1, x: 0 }} transition={{ delay: 0.25 }}\n            style={{ padding: 18, borderRadius: 16, background: \"linear-gradient(135deg,#2D1B69,#1a0f3c)\", border: \"1px solid rgba(107,53,232,0.3)\", position: \"relative\", overflow: \"hidden\" }}>\n            <div style={{ position: \"absolute\", top: -20, right: -20, width: 80, height: 80, borderRadius: \"50%\", background: \"rgba(107,53,232,0.15)\" }} />\n            <div style={{ display: \"flex\", alignItems: \"center\", gap: 8, marginBottom: 8 }}>\n              <div style={{ width: 28, height: 28, borderRadius: 8, background: \"rgba(107,53,232,0.3)\", display: \"flex\", alignItems: \"center\", justifyContent: \"center\" }}>\n                <Zap size={13} color={V.v300} />\n              </div>\n              <span style={{ fontSize: 12, fontWeight: 700, color: V.v300 }}>KIRO</span>\n            </div>\n            <p style={{ fontSize: 13, fontWeight: 700, color: \"#fff\", marginBottom: 6 }}>What do you want to build today?</p>\n            <p style={{ fontSize: 11, color: \"rgba(255,255,255,0.5)\", marginBottom: 14, lineHeight: 1.5 }}>\n              Import products, write copy, run a sale, or just ask anything about your store.\n            </p>\n            <Link href=\"/kiro\">\n              <button style={{ width: \"100%\", padding: \"9px 0\", borderRadius: 10, border: \"none\", cursor: \"pointer\", background: \"rgba(107,53,232,0.4)\", color: \"#fff\", fontSize: 12, fontWeight: 700, display: \"flex\", alignItems: \"center\", justifyContent: \"center\", gap: 6 }}>\n                <Zap size={12} /> Chat with KIRO\n              </button>\n            </Link>\n          </motion.div>\n\n          {/* Quick Actions */}\n          <motion.div initial={{ opacity: 0, x: 16 }} animate={{ opacity: 1, x: 0 }} transition={{ delay: 0.32 }}\n            style={{ padding: 18, borderRadius: 16, background: t.card, border: `1px solid ${t.border}` }}>\n            <span style={{ fontSize: 13, fontWeight: 700, color: t.text, display: \"block\", marginBottom: 12 }}>Quick Actions</span>\n            <div style={{ display: \"grid\", gridTemplateColumns: \"1fr 1fr\", gap: 8 }}>\n              {quickActions.map(a => {\n                const Icon = a.icon;\n                return (\n                  <Link key={a.label} href={a.href} target={(a as any).target} style={{ textDecoration: \"none\" }}>\n                    <motion.div whileHover={{ scale: 1.02 }} whileTap={{ scale: 0.97 }}\n                      style={{ display: \"flex\", flexDirection: \"column\", alignItems: \"center\", gap: 7, padding: 12, borderRadius: 12, cursor: \"pointer\", background: t.faint, border: `1px solid ${t.border}` }}>\n                      <div style={{ width: 30, height: 30, borderRadius: 9, display: \"flex\", alignItems: \"center\", justifyContent: \"center\", background: `${a.color}15` }}>\n                        <Icon size={14} color={a.color} />\n                      </div>\n                      <span style={{ fontSize: 11, fontWeight: 600, color: t.muted, textAlign: \"center\" }}>{a.label}</span>\n                    </motion.div>\n                  </Link>\n                );\n              })}\n            </div>\n          </motion.div>\n\n          {/* Store status */}\n          <motion.div initial={{ opacity: 0, x: 16 }} animate={{ opacity: 1, x: 0 }} transition={{ delay: 0.38 }}\n            style={{ padding: 18, borderRadius: 16, background: t.card, border: `1px solid ${t.border}` }}>\n            <span style={{ fontSize: 13, fontWeight: 700, color: t.text, display: \"block\", marginBottom: 12 }}>Store Status</span>\n            <div style={{ display: \"flex\", flexDirection: \"column\", gap: 8 }}>\n              {[\n                { label: \"Store live\",     done: !!user?.stores?.[0]?.id,                                                                               icon: Store        },\n                { label: \"Products added\", done: (productCount || stats?.products || analytics?.totalProducts || 0) > 0,              icon: Package      },\n                { label: \"First order\",    done: orders.length > 0 || (stats?.orders || analytics?.totalOrders || 0) > 0,                             icon: ShoppingCart },\n                { label: \"Payment setup\",  done: !!(user?.stores?.[0] as any)?.paystackPublicKey || !!(user?.stores?.[0] as any)?.stripeAccountId || !!(user?.stores?.[0] as any)?.currency, icon: CheckCircle2 },\n              ].map(item => {\n                const Icon = item.icon;\n                return (\n                  <div key={item.label} style={{ display: \"flex\", alignItems: \"center\", gap: 8 }}>\n                    <div style={{ width: 22, height: 22, borderRadius: 6, display: \"flex\", alignItems: \"center\", justifyContent: \"center\", background: item.done ? \"rgba(16,185,129,0.1)\" : t.faint, flexShrink: 0 }}>\n                      <Icon size={11} color={item.done ? V.green : t.muted} />\n                    </div>\n                    <span style={{ fontSize: 12, color: item.done ? t.text : t.muted, flex: 1 }}>{item.label}</span>\n                    {item.done\n                      ? <CheckCircle2 size={13} color={V.green} />\n                      : <Clock size={13} style={{ color: t.muted }} />}\n                  </div>\n                );\n              })}\n            </div>\n          </motion.div>\n        </div>\n      </div>\n\n      <style>{`\n        @media(max-width:900px){\n          .grid-cols-2{grid-template-columns:1fr 1fr!important}\n          .grid-1col.lg\\\\:grid-2col{grid-template-columns:1fr!important}\n        }\n        @media(max-width:480px){\n          .grid-cols-2{grid-template-columns:1fr 1fr!important}\n        }\n      `}</style>\n    </div>\n  );\n}\n","frontend/src/app/not-found.tsx":"import Link from \"next/link\";\n\nexport default function NotFound() {\n  return (\n    <div style={{ minHeight:\"100vh\", display:\"flex\", flexDirection:\"column\", alignItems:\"center\", justifyContent:\"center\", gap:16, padding:24, background:\"#F4F2FB\", fontFamily:\"'Plus Jakarta Sans',system-ui,sans-serif\" }}>\n      <div style={{ width:64, height:64, borderRadius:18, background:\"linear-gradient(145deg,#2D1B69,#0D0625)\", display:\"flex\", alignItems:\"center\", justifyContent:\"center\" }}>\n        <svg width=\"26\" height=\"26\" viewBox=\"0 0 24 24\" fill=\"none\"><path d=\"M13 2L3 14h9l-1 8 10-12h-9z\" fill=\"white\"/></svg>\n      </div>\n      <div style={{ textAlign:\"center\" }}>\n        <p style={{ fontSize:80, fontWeight:900, color:\"#130D2E\", margin:\"0 0 8px\", letterSpacing:\"-0.06em\", lineHeight:1, opacity:0.08 }}>404</p>\n        <h1 style={{ fontSize:24, fontWeight:800, color:\"#130D2E\", margin:\"-40px 0 10px\", letterSpacing:\"-0.03em\" }}>Page not found</h1>\n        <p style={{ fontSize:15, color:\"rgba(19,13,46,0.5)\", margin:\"0 0 28px\" }}>This page doesn't exist or was moved.</p>\n        <div style={{ display:\"flex\", gap:10, justifyContent:\"center\", flexWrap:\"wrap\" }}>\n          <Link href=\"/dashboard\" style={{ display:\"inline-flex\", alignItems:\"center\", gap:6, padding:\"11px 22px\", borderRadius:12, background:\"#130D2E\", color:\"#fff\", textDecoration:\"none\", fontSize:14, fontWeight:700 }}>\n            Go to dashboard\n          </Link>\n          <Link href=\"/\" style={{ display:\"inline-flex\", alignItems:\"center\", gap:6, padding:\"11px 22px\", borderRadius:12, background:\"transparent\", color:\"rgba(19,13,46,0.5)\", textDecoration:\"none\", fontSize:14, fontWeight:600, border:\"1px solid rgba(19,13,46,0.1)\" }}>\n            Home\n          </Link>\n        </div>\n      </div>\n    </div>\n  );\n}\n","frontend/src/app/error.tsx":"\"use client\";\nimport { useEffect } from \"react\";\nimport Link from \"next/link\";\n\nexport default function GlobalError({ error, reset }: { error: Error & { digest?: string }; reset: () => void }) {\n  useEffect(() => { console.error(error); }, [error]);\n\n  const isNetworkError = error.message?.includes(\"fetch\") || error.message?.includes(\"network\") || error.message?.includes(\"ECONNREFUSED\");\n\n  return (\n    <div style={{ minHeight:\"100vh\", display:\"flex\", flexDirection:\"column\", alignItems:\"center\", justifyContent:\"center\", gap:16, padding:24, background:\"#F4F2FB\", fontFamily:\"system-ui,sans-serif\" }}>\n      <div style={{ width:56, height:56, borderRadius:16, background:\"linear-gradient(145deg,#2D1B69,#0D0625)\", display:\"flex\", alignItems:\"center\", justifyContent:\"center\" }}>\n        <svg width=\"22\" height=\"22\" viewBox=\"0 0 24 24\" fill=\"none\"><path d=\"M13 2L3 14h9l-1 8 10-12h-9z\" fill=\"white\"/></svg>\n      </div>\n      <div style={{ textAlign:\"center\", maxWidth:420 }}>\n        <h1 style={{ fontSize:22, fontWeight:800, color:\"#130D2E\", margin:\"0 0 8px\" }}>\n          {isNetworkError ? \"Connection issue\" : \"Something went wrong\"}\n        </h1>\n        <p style={{ fontSize:14, color:\"rgba(19,13,46,0.5)\", margin:\"0 0 24px\", lineHeight:1.6 }}>\n          {isNetworkError\n            ? \"We're having trouble connecting. This usually resolves itself in 30 seconds.\"\n            : \"An unexpected error occurred. Please try refreshing the page.\"}\n        </p>\n        <div style={{ display:\"flex\", gap:10, justifyContent:\"center\", flexWrap:\"wrap\" }}>\n          <button onClick={reset}\n            style={{ padding:\"11px 22px\", borderRadius:12, background:\"#130D2E\", color:\"#fff\", border:\"none\", cursor:\"pointer\", fontSize:14, fontWeight:700, fontFamily:\"inherit\" }}>\n            Try again\n          </button>\n          <Link href=\"/dashboard\"\n            style={{ padding:\"11px 22px\", borderRadius:12, background:\"transparent\", color:\"rgba(19,13,46,0.5)\", textDecoration:\"none\", fontSize:14, fontWeight:600, border:\"1px solid rgba(19,13,46,0.1)\" }}>\n            Dashboard\n          </Link>\n        </div>\n      </div>\n    </div>\n  );\n}\n","frontend/src/app/(marketing)/how-it-works/page.tsx":"import Link from \"next/link\";\nimport { ArrowRight, Zap, Package, Store, TrendingUp, Check } from \"lucide-react\";\n\nconst C = { bg:\"#F4F2FB\", navy:\"#130D2E\", purple:\"#6B35E8\", muted:\"rgba(19,13,46,0.5)\", border:\"rgba(107,53,232,0.1)\", faint:\"rgba(107,53,232,0.04)\" };\n\nconst STEPS = [\n  {\n    n:1, icon:Store, color:\"#6B35E8\",\n    title:\"Create your account\",\n    desc:\"Sign up in 30 seconds. Pick your niche, choose a store template, and your store is live immediately — no design skills needed.\",\n    details:[\"Choose from 29 industry templates\",\"Custom domain (your own brand)\",\"Mobile-optimised storefront\",\"Full KIRO AI from day one\"],\n  },\n  {\n    n:2, icon:Package, color:\"#0EA5E9\",\n    title:\"Import products instantly\",\n    desc:\"Paste any product URL from AliExpress, Temu, Amazon, or CJDropshipping. KIRO scores it A–F, rewrites the description, and sets a profitable price.\",\n    details:[\"Paste any supplier URL\",\"KIRO grades every product A–F\",\"Auto-pricing for healthy margins\",\"Bulk import entire stores\"],\n  },\n  {\n    n:3, icon:Zap, color:\"#10B981\",\n    title:\"KIRO runs your store\",\n    desc:\"KIRO monitors your store 24/7. It alerts you to opportunities, writes your marketing copy, and handles customer queries — automatically.\",\n    details:[\"Daily revenue insights\",\"Flash sale automation\",\"Abandoned cart recovery\",\"Product description writing\"],\n  },\n  {\n    n:4, icon:TrendingUp, color:\"#F59E0B\",\n    title:\"Get paid, grow fast\",\n    desc:\"Accept payments via Paystack (card, bank transfer, USSD) and Stripe. Money hits your account directly — no middleman, no delay.\",\n    details:[\"Paystack for local payments\",\"Stripe for international orders\",\"Automatic order fulfilment via CJ\",\"Real-time revenue tracking\"],\n  },\n];\n\nexport default function HowItWorksPage() {\n  return (\n    <div style={{ fontFamily:\"'Plus Jakarta Sans',system-ui,sans-serif\" }}>\n      <style>{`@import url('https://fonts.googleapis.com/css2?family=Fraunces:ital,wght@0,400;0,500;1,400;1,500&family=Plus+Jakarta+Sans:wght@400;500;600;700;800;900&display=swap');`}</style>\n\n      {/* Hero */}\n      <section style={{ padding:\"80px 24px 60px\", textAlign:\"center\", maxWidth:680, margin:\"0 auto\" }}>\n        <p style={{ fontSize:11, fontWeight:700, letterSpacing:\"0.12em\", color:C.purple, marginBottom:12, textTransform:\"uppercase\" }}>HOW IT WORKS</p>\n        <h1 style={{ fontFamily:\"'Fraunces',Georgia,serif\", fontSize:\"clamp(36px,6vw,56px)\", fontWeight:500, letterSpacing:\"-0.04em\", color:C.navy, margin:\"0 0 16px\", lineHeight:1.08 }}>\n          From zero to<br/><em style={{ fontStyle:\"italic\", color:C.purple }}>first sale.</em>\n        </h1>\n        <p style={{ fontSize:16, color:C.muted, margin:\"0 auto\", lineHeight:1.6, maxWidth:460 }}>\n          Four steps. Sixty seconds to launch. Everything else runs itself.\n        </p>\n      </section>\n\n      {/* Steps */}\n      <section style={{ maxWidth:900, margin:\"0 auto\", padding:\"0 24px 80px\" }}>\n        <div style={{ display:\"flex\", flexDirection:\"column\", gap:3 }}>\n          {STEPS.map((step, idx) => {\n            const Icon = step.icon;\n            return (\n              <div key={step.n} style={{\n                display:\"grid\", gridTemplateColumns:\"1fr 1fr\", gap:40, alignItems:\"center\",\n                padding:\"56px 48px\", background:\"#fff\", borderRadius:24,\n                border:`1px solid ${C.border}`, boxShadow:\"0 2px 16px rgba(107,53,232,0.04)\",\n                direction: idx%2===1?\"rtl\":\"ltr\",\n              }} className=\"step-row\">\n                {/* Text */}\n                <div style={{ direction:\"ltr\" }}>\n                  <div style={{ display:\"flex\", alignItems:\"center\", gap:12, marginBottom:20 }}>\n                    <div style={{ width:40, height:40, borderRadius:12, background:`${step.color}12`, display:\"flex\", alignItems:\"center\", justifyContent:\"center\" }}>\n                      <Icon size={18} color={step.color}/>\n                    </div>\n                    <span style={{ fontSize:11, fontWeight:800, letterSpacing:\"0.1em\", color:step.color, textTransform:\"uppercase\" }}>Step {step.n}</span>\n                  </div>\n                  <h2 style={{ fontFamily:\"'Fraunces',Georgia,serif\", fontSize:\"clamp(24px,3.5vw,34px)\", fontWeight:500, color:C.navy, margin:\"0 0 14px\", letterSpacing:\"-0.03em\", lineHeight:1.15 }}>\n                    {step.title}\n                  </h2>\n                  <p style={{ fontSize:15, color:C.muted, lineHeight:1.65, margin:\"0 0 24px\" }}>{step.desc}</p>\n                  <div style={{ display:\"flex\", flexDirection:\"column\", gap:8 }}>\n                    {step.details.map(d => (\n                      <div key={d} style={{ display:\"flex\", alignItems:\"center\", gap:8 }}>\n                        <Check size={13} color={step.color} strokeWidth={2.5}/>\n                        <span style={{ fontSize:13, color:C.muted, fontWeight:500 }}>{d}</span>\n                      </div>\n                    ))}\n                  </div>\n                </div>\n\n                {/* Visual */}\n                <div style={{ direction:\"ltr\" }}>\n                  <div style={{\n                    aspectRatio:\"4/3\", borderRadius:20,\n                    background:`linear-gradient(135deg,${step.color}08,${step.color}18)`,\n                    border:`1px solid ${step.color}20`,\n                    display:\"flex\", alignItems:\"center\", justifyContent:\"center\",\n                  }}>\n                    <div style={{ textAlign:\"center\" }}>\n                      <div style={{ width:80, height:80, borderRadius:24, background:`${step.color}15`, display:\"flex\", alignItems:\"center\", justifyContent:\"center\", margin:\"0 auto 16px\" }}>\n                        <Icon size={36} color={step.color}/>\n                      </div>\n                      <span style={{ fontSize:32, fontWeight:900, color:step.color, display:\"block\", lineHeight:1 }}>0{step.n}</span>\n                      <span style={{ fontSize:12, color:`${step.color}80`, fontWeight:600, marginTop:4, display:\"block\" }}>{step.title}</span>\n                    </div>\n                  </div>\n                </div>\n              </div>\n            );\n          })}\n        </div>\n      </section>\n\n      {/* Stats */}\n      <section style={{ background:\"#fff\", padding:\"64px 24px\", borderTop:`1px solid ${C.border}` }}>\n        <div style={{ maxWidth:800, margin:\"0 auto\", display:\"grid\", gridTemplateColumns:\"repeat(4,1fr)\", gap:32, textAlign:\"center\" }} className=\"stats-g\">\n          {[\n            { n:\"60s\",   l:\"To launch a store\"   },\n            { n:\"29\",    l:\"Store templates\"      },\n            { n:\"22\",    l:\"KIRO commands\"         },\n            { n:\"50+\",   l:\"Payment currencies\"   },\n          ].map(s => (\n            <div key={s.l}>\n              <p style={{ fontFamily:\"'Fraunces',Georgia,serif\", fontSize:\"clamp(32px,5vw,48px)\", fontWeight:500, color:C.navy, margin:\"0 0 6px\", letterSpacing:\"-0.04em\" }}>{s.n}</p>\n              <p style={{ fontSize:13, color:C.muted, margin:0 }}>{s.l}</p>\n            </div>\n          ))}\n        </div>\n      </section>\n\n      {/* CTA */}\n      <section style={{ padding:\"80px 24px\", textAlign:\"center\", background:\"linear-gradient(160deg,#2D1B69,#0D0625)\" }}>\n        <h2 style={{ fontFamily:\"'Fraunces',Georgia,serif\", fontSize:\"clamp(28px,5vw,48px)\", fontWeight:500, color:\"#fff\", margin:\"0 0 14px\", letterSpacing:\"-0.03em\" }}>\n          Ready to see it live?\n        </h2>\n        <p style={{ fontSize:15, color:\"rgba(255,255,255,0.5)\", marginBottom:36 }}>Your store is 60 seconds away. Free forever.</p>\n        <Link href=\"/auth/register\" style={{ display:\"inline-flex\", alignItems:\"center\", gap:8, padding:\"14px 32px\", borderRadius:14, background:\"#fff\", color:C.navy, textDecoration:\"none\", fontSize:14, fontWeight:700, boxShadow:\"0 8px 24px rgba(0,0,0,0.2)\" }}>\n          Launch your store free <ArrowRight size={14}/>\n        </Link>\n      </section>\n\n      <style>{`\n        @media(max-width:768px){ .step-row{grid-template-columns:1fr!important;direction:ltr!important;padding:32px 24px!important;} .stats-g{grid-template-columns:1fr 1fr!important;} }\n      `}</style>\n    </div>\n  );\n}\n","frontend/src/app/(marketing)/pricing/page.tsx":"\"use client\";\nimport { useState, useEffect } from \"react\";\nimport Link from \"next/link\";\nimport { Check, X, ArrowRight, Zap } from \"lucide-react\";\n\nconst C = { bg:\"#F4F2FB\", navy:\"#130D2E\", purple:\"#6B35E8\", muted:\"rgba(19,13,46,0.5)\", border:\"rgba(107,53,232,0.1)\", faint:\"rgba(107,53,232,0.04)\" };\n\nconst CURRENCIES: Record<string,{symbol:string;growth:number;pro:number;locale:string}> = {\n  NGN: { symbol:\"₦\", growth:9500,   pro:25000,  locale:\"en-NG\" },\n  USD: { symbol:\"$\", growth:6,      pro:16,     locale:\"en-US\" },\n  GBP: { symbol:\"£\", growth:5,      pro:14,     locale:\"en-GB\" },\n  GHS: { symbol:\"₵\", growth:89,     pro:240,    locale:\"en-GH\" },\n  KES: { symbol:\"KSh\",growth:1300,  pro:3500,   locale:\"en-KE\" },\n};\n\nfunction detectCurrency(): string {\n  if(typeof window===\"undefined\") return \"USD\";\n  try {\n    const tz = Intl.DateTimeFormat().resolvedOptions().timeZone;\n    if(tz.includes(\"Lagos\")||tz.includes(\"Abuja\")) return \"NGN\";\n    if(tz.includes(\"Accra\")) return \"GHS\";\n    if(tz.includes(\"Nairobi\")) return \"KES\";\n    if(tz.includes(\"London\")) return \"GBP\";\n  } catch {}\n  return \"USD\";\n}\n\nfunction fmt(n:number, code:string) {\n  const c = CURRENCIES[code];\n  return `${c.symbol}${n.toLocaleString()}`;\n}\n\nexport default function PricingPage() {\n  const [currency, setCurrency] = useState(\"USD\");\n  const [annual, setAnnual] = useState(false);\n  useEffect(()=>{ setCurrency(detectCurrency()); },[]);\n\n  const cur = CURRENCIES[currency];\n  const mult = annual ? 0.8 : 1;\n\n  const plans = [\n    {\n      name:\"Free\", tag:\"Try it, no commitment.\",\n      price:\"0\", period:\"/mo\",\n      cta:\"Start free\", ctaHref:\"/auth/register\", highlight:false,\n      features:[\n        {t:\"1 store\",ok:true},{t:\"20 products\",ok:true},\n        {t:\"KIRO — 10 messages/day\",ok:true},{t:\"Basic analytics\",ok:true},\n        {t:\"Paystack payments\",ok:true},{t:\"2% transaction fee\",ok:false},\n        {t:\"Custom domain\",ok:false},{t:\"Email campaigns\",ok:false},\n      ],\n    },\n    {\n      name:\"Growth\", tag:\"For serious sellers.\",\n      price:Math.round(cur.growth*mult).toLocaleString(), period:\"/mo\",\n      trial:\"14-day free trial\",\n      cta:\"Start 14-day trial\", ctaHref:\"/auth/register\", highlight:true,\n      features:[\n        {t:\"5 stores\",ok:true},{t:\"Unlimited products\",ok:true},\n        {t:\"Full KIRO — unlimited\",ok:true},{t:\"Full analytics\",ok:true},\n        {t:\"Paystack + Stripe\",ok:true},{t:\"0% transaction fee\",ok:true},\n        {t:\"Custom domain\",ok:true},{t:\"Coupons & flash sales\",ok:true},\n        {t:\"Abandoned cart recovery\",ok:true},{t:\"Email campaigns\",ok:true},\n      ],\n    },\n    {\n      name:\"Pro\", tag:\"Fully automated business.\",\n      price:Math.round(cur.pro*mult).toLocaleString(), period:\"/mo\",\n      cta:\"Start Pro\", ctaHref:\"/auth/register\", highlight:false,\n      features:[\n        {t:\"Unlimited stores\",ok:true},{t:\"Everything in Growth\",ok:true},\n        {t:\"KIRO Pro intelligence\",ok:true},{t:\"API access\",ok:true},\n        {t:\"3 staff accounts\",ok:true},{t:\"Priority support (2hr)\",ok:true},\n        {t:\"20% referral commissions\",ok:true},{t:\"White label option\",ok:true},\n      ],\n    },\n  ];\n\n  const faqs = [\n    [\"Can I change plans anytime?\",\"Yes. Upgrade or downgrade any time from your billing settings. Changes take effect immediately.\"],\n    [\"Is there a free trial?\",\"The Growth plan comes with a 14-day free trial. No card required to start.\"],\n    [\"What is the 2% transaction fee?\",\"On the Free plan, DropOS takes 2% of every order value. Growth and Pro plans have 0% transaction fees — you keep everything.\"],\n    [\"Do you support currencies other than NGN?\",\"Yes. DropOS supports 50+ currencies. Accept Naira, Pounds, Dollars, Cedis, and more.\"],\n    [\"Can I cancel anytime?\",\"Yes. Cancel from your dashboard with no penalties. You keep access until the end of your billing period.\"],\n    [\"What payment methods do you support?\",\"Paystack (card, bank transfer, USSD) for African payments. Stripe for international card payments.\"],\n  ];\n\n  return (\n    <div style={{ fontFamily:\"'Plus Jakarta Sans',system-ui,sans-serif\" }}>\n      <style>{`@import url('https://fonts.googleapis.com/css2?family=Fraunces:ital,wght@0,400;0,500;1,400;1,500&family=Plus+Jakarta+Sans:wght@400;500;600;700;800;900&display=swap');`}</style>\n\n      {/* Hero */}\n      <section style={{ padding:\"80px 24px 60px\", textAlign:\"center\", maxWidth:700, margin:\"0 auto\" }}>\n        <p style={{ fontSize:11, fontWeight:700, letterSpacing:\"0.12em\", color:C.purple, marginBottom:12, textTransform:\"uppercase\" }}>PRICING</p>\n        <h1 style={{ fontFamily:\"'Fraunces',Georgia,serif\", fontSize:\"clamp(36px,6vw,56px)\", fontWeight:500, letterSpacing:\"-0.04em\", color:C.navy, margin:\"0 0 16px\", lineHeight:1.08 }}>\n          Simple, honest<br/><em style={{ fontStyle:\"italic\", color:C.purple }}>pricing.</em>\n        </h1>\n        <p style={{ fontSize:16, color:C.muted, maxWidth:420, margin:\"0 auto 32px\", lineHeight:1.6 }}>\n          No hidden fees. No lock-in. Start free and grow at your pace.\n        </p>\n\n        {/* Toggles */}\n        <div style={{ display:\"flex\", alignItems:\"center\", justifyContent:\"center\", gap:16, flexWrap:\"wrap\" }}>\n          {/* Currency selector */}\n          <div style={{ display:\"flex\", background:\"#fff\", borderRadius:10, padding:4, border:`1px solid ${C.border}`, gap:2 }}>\n            {Object.keys(CURRENCIES).map(c => (\n              <button key={c} onClick={()=>setCurrency(c)}\n                style={{ padding:\"6px 12px\", borderRadius:7, border:\"none\", cursor:\"pointer\", fontSize:12, fontWeight:700, fontFamily:\"inherit\", background:currency===c ? C.navy : \"transparent\", color:currency===c ? \"#fff\" : C.muted, transition:\"all 0.15s\" }}>\n                {c}\n              </button>\n            ))}\n          </div>\n          {/* Annual toggle */}\n          <div style={{ display:\"flex\", alignItems:\"center\", gap:8, background:\"#fff\", borderRadius:10, padding:\"8px 14px\", border:`1px solid ${C.border}` }}>\n            <span style={{ fontSize:12, fontWeight:600, color:C.muted }}>Monthly</span>\n            <button onClick={()=>setAnnual(!annual)}\n              style={{ width:40, height:22, borderRadius:11, border:\"none\", cursor:\"pointer\", background:annual?C.purple:\"rgba(19,13,46,0.12)\", position:\"relative\", transition:\"background 0.2s\", padding:0 }}>\n              <div style={{ position:\"absolute\", top:3, left:annual?21:3, width:16, height:16, borderRadius:\"50%\", background:\"#fff\", transition:\"left 0.2s\", boxShadow:\"0 1px 3px rgba(0,0,0,0.15)\" }}/>\n            </button>\n            <span style={{ fontSize:12, fontWeight:600, color:annual?C.purple:C.muted }}>Annual <span style={{ background:\"rgba(107,53,232,0.1)\", color:C.purple, padding:\"1px 6px\", borderRadius:4, fontSize:10, fontWeight:700 }}>-20%</span></span>\n          </div>\n        </div>\n      </section>\n\n      {/* Plans */}\n      <section style={{ maxWidth:1040, margin:\"0 auto\", padding:\"0 24px 80px\", display:\"grid\", gridTemplateColumns:\"repeat(3,1fr)\", gap:16 }} className=\"plans-grid\">\n        {plans.map(plan => (\n          <div key={plan.name} style={{\n            background:plan.highlight?\"linear-gradient(160deg,#2D1B69,#1A0B4A)\":\"#fff\",\n            borderRadius:20, padding:\"32px 28px\",\n            border:plan.highlight?\"1px solid rgba(196,181,253,0.3)\":`1px solid ${C.border}`,\n            position:\"relative\",\n            boxShadow:plan.highlight?\"0 20px 60px rgba(45,27,105,0.25)\":\"0 2px 16px rgba(107,53,232,0.06)\",\n          }}>\n            {plan.highlight && (\n              <div style={{ position:\"absolute\", top:-13, left:\"50%\", transform:\"translateX(-50%)\", background:\"#C4B5FD\", color:\"#130D2E\", fontSize:10, fontWeight:800, padding:\"4px 16px\", borderRadius:99, whiteSpace:\"nowrap\", letterSpacing:\"0.06em\" }}>\n                MOST POPULAR\n              </div>\n            )}\n            <p style={{ fontSize:20, fontWeight:800, color:plan.highlight?\"#fff\":C.navy, margin:\"0 0 4px\", letterSpacing:\"-0.02em\" }}>{plan.name}</p>\n            <p style={{ fontSize:13, color:plan.highlight?\"rgba(255,255,255,0.55)\":C.muted, margin:\"0 0 20px\" }}>{plan.tag}</p>\n            <div style={{ display:\"flex\", alignItems:\"baseline\", gap:4, marginBottom:4 }}>\n              <span style={{ fontSize:13, fontWeight:700, color:plan.highlight?\"rgba(255,255,255,0.6)\":C.muted }}>{cur.symbol}</span>\n              <span style={{ fontSize:40, fontWeight:900, color:plan.highlight?\"#fff\":C.navy, letterSpacing:\"-0.04em\" }}>{plan.price}</span>\n              <span style={{ fontSize:13, color:plan.highlight?\"rgba(255,255,255,0.4)\":C.muted }}>{plan.period}</span>\n            </div>\n            {plan.trial && <p style={{ fontSize:12, color:\"#A78BFA\", fontWeight:700, margin:\"0 0 20px\" }}>{plan.trial}</p>}\n            {!plan.trial && <div style={{ height:20, marginBottom:20 }}/>}\n\n            <div style={{ borderTop:`1px solid ${plan.highlight?\"rgba(255,255,255,0.1)\":C.border}`, paddingTop:20, marginBottom:24 }}>\n              {plan.features.map(f => (\n                <div key={f.t} style={{ display:\"flex\", alignItems:\"center\", gap:8, marginBottom:10 }}>\n                  {f.ok\n                    ? <Check size={13} color={plan.highlight?\"#A78BFA\":C.purple} strokeWidth={2.5}/>\n                    : <X size={13} color={plan.highlight?\"rgba(255,255,255,0.2)\":\"rgba(19,13,46,0.2)\"} strokeWidth={2}/>\n                  }\n                  <span style={{ fontSize:13, color:f.ok?(plan.highlight?\"rgba(255,255,255,0.85)\":C.navy):(plan.highlight?\"rgba(255,255,255,0.3)\":\"rgba(19,13,46,0.3)\"), textDecoration:f.ok?\"none\":\"line-through\" }}>\n                    {f.t}\n                  </span>\n                </div>\n              ))}\n            </div>\n\n            <Link href={plan.ctaHref} style={{\n              display:\"flex\", alignItems:\"center\", justifyContent:\"center\", gap:6,\n              padding:\"13px 0\", borderRadius:12, textDecoration:\"none\",\n              fontSize:14, fontWeight:700,\n              background:plan.highlight?\"#fff\":\"transparent\",\n              color:plan.highlight?C.navy:C.navy,\n              border:plan.highlight?\"none\":`1px solid ${C.border}`,\n            }}>\n              {plan.cta} {plan.highlight && <ArrowRight size={14}/>}\n            </Link>\n          </div>\n        ))}\n      </section>\n\n      {/* FAQ */}\n      <section style={{ maxWidth:720, margin:\"0 auto\", padding:\"0 24px 100px\" }}>\n        <h2 style={{ fontFamily:\"'Fraunces',Georgia,serif\", fontSize:\"clamp(28px,4vw,40px)\", fontWeight:500, color:C.navy, textAlign:\"center\", margin:\"0 0 48px\", letterSpacing:\"-0.03em\" }}>\n          Common <em style={{ fontStyle:\"italic\", color:C.purple }}>questions</em>\n        </h2>\n        <div style={{ display:\"flex\", flexDirection:\"column\", gap:2 }}>\n          {faqs.map(([q, a]) => (\n            <details key={q} style={{ background:\"#fff\", borderRadius:14, border:`1px solid ${C.border}`, overflow:\"hidden\" }}>\n              <summary style={{ padding:\"18px 20px\", fontSize:14, fontWeight:700, color:C.navy, cursor:\"pointer\", listStyle:\"none\", display:\"flex\", justifyContent:\"space-between\", alignItems:\"center\" }}>\n                {q}\n                <span style={{ color:C.purple, fontSize:18, fontWeight:400, flexShrink:0, marginLeft:12 }}>+</span>\n              </summary>\n              <div style={{ padding:\"0 20px 18px\", fontSize:14, color:C.muted, lineHeight:1.65 }}>{a}</div>\n            </details>\n          ))}\n        </div>\n      </section>\n\n      {/* CTA */}\n      <section style={{ background:\"linear-gradient(160deg,#2D1B69,#0D0625)\", padding:\"80px 24px\", textAlign:\"center\" }}>\n        <h2 style={{ fontFamily:\"'Fraunces',Georgia,serif\", fontSize:\"clamp(28px,5vw,48px)\", fontWeight:500, color:\"#fff\", margin:\"0 0 16px\", letterSpacing:\"-0.03em\" }}>\n          Ready to start?\n        </h2>\n        <p style={{ fontSize:16, color:\"rgba(255,255,255,0.55)\", marginBottom:36 }}>Free forever. No card needed.</p>\n        <Link href=\"/auth/register\" style={{ display:\"inline-flex\", alignItems:\"center\", gap:8, padding:\"14px 32px\", borderRadius:14, background:\"#fff\", color:C.navy, textDecoration:\"none\", fontSize:14, fontWeight:700, boxShadow:\"0 8px 24px rgba(0,0,0,0.2)\" }}>\n          Start free <ArrowRight size={14}/>\n        </Link>\n      </section>\n\n      <style>{`\n        @media(max-width:768px){ .plans-grid{grid-template-columns:1fr!important;} }\n        details summary::-webkit-details-marker{display:none}\n        details[open] summary span{transform:rotate(45deg);}\n        details summary span{transition:transform 0.2s;display:inline-block;}\n      `}</style>\n    </div>\n  );\n}\n","frontend/src/components/HomePage.tsx":"\"use client\";\nimport { useState, useEffect, useRef } from \"react\";\nimport { motion, useScroll, useTransform, AnimatePresence } from \"framer-motion\";\nimport Link from \"next/link\";\nimport {\n  Zap, ArrowRight, Check, Store, Package, BarChart3,\n  ShoppingCart, Globe, Shield, TrendingUp, Sparkles,\n  ChevronRight, Star, Play, Menu, X, MessageSquare,\n} from \"lucide-react\";\n\n// ─── Brand colors (matches dashboard + auth) ─────────────────────────────────\nconst C = {\n  bg:      \"#F4F2FB\",\n  navy:    \"#130D2E\",\n  purple:  \"#6B35E8\",\n  violet:  \"#2D1B69\",\n  muted:   \"rgba(19,13,46,0.5)\",\n  faint:   \"rgba(107,53,232,0.06)\",\n  border:  \"rgba(107,53,232,0.1)\",\n};\n\nconst API = process.env.NEXT_PUBLIC_API_URL || \"\";\n\n// ─── Nav ──────────────────────────────────────────────────────────────────────\nfunction Nav() {\n  const [scrolled, setScrolled] = useState(false);\n  const [mobileOpen, setMobileOpen] = useState(false);\n\n  useEffect(() => {\n    const fn = () => setScrolled(window.scrollY > 20);\n    window.addEventListener(\"scroll\", fn);\n    return () => window.removeEventListener(\"scroll\", fn);\n  }, []);\n\n  return (\n    <>\n      <nav style={{\n        position: \"fixed\", top: 0, left: 0, right: 0, zIndex: 100,\n        padding: \"0 24px\",\n        height: 64,\n        display: \"flex\", alignItems: \"center\", justifyContent: \"space-between\",\n        background: scrolled ? \"rgba(244,242,251,0.92)\" : \"transparent\",\n        backdropFilter: scrolled ? \"blur(20px)\" : \"none\",\n        borderBottom: scrolled ? `1px solid ${C.border}` : \"1px solid transparent\",\n        transition: \"all 0.3s ease\",\n      }}>\n        {/* Logo */}\n        <Link href=\"/\" style={{ display: \"flex\", alignItems: \"center\", gap: 10, textDecoration: \"none\" }}>\n          <div style={{\n            width: 32, height: 32, borderRadius: 9,\n            background: \"linear-gradient(145deg,#2D1B69,#0D0625)\",\n            display: \"flex\", alignItems: \"center\", justifyContent: \"center\",\n            boxShadow: \"0 4px 12px rgba(45,27,105,0.3)\",\n          }}>\n            <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\">\n              <path d=\"M13 2L3 14h9l-1 8 10-12h-9z\" fill=\"white\"/>\n            </svg>\n          </div>\n          <span style={{ fontSize: 16, fontWeight: 800, color: C.navy, letterSpacing: \"-0.02em\" }}>DropOS</span>\n        </Link>\n\n        {/* Desktop nav */}\n        <div className=\"nav-links\" style={{ display: \"flex\", alignItems: \"center\", gap: 6 }}>\n          {[\n            { label: \"Features\",   href: \"/features\"  },\n            { label: \"Pricing\",    href: \"/pricing\"    },\n            { label: \"How it works\", href: \"/how-it-works\" },\n          ].map(l => (\n            <Link key={l.label} href={l.href}\n              style={{ fontSize: 13, fontWeight: 500, color: C.muted, textDecoration: \"none\", padding: \"6px 12px\", borderRadius: 8, transition: \"all 0.15s\" }}\n              onMouseEnter={e => { e.currentTarget.style.color = C.navy; e.currentTarget.style.background = C.faint; }}\n              onMouseLeave={e => { e.currentTarget.style.color = C.muted; e.currentTarget.style.background = \"transparent\"; }}>\n              {l.label}\n            </Link>\n          ))}\n        </div>\n\n        {/* CTA */}\n        <div className=\"nav-cta\" style={{ display: \"flex\", alignItems: \"center\", gap: 10 }}>\n          <Link href=\"/auth/login\" style={{ fontSize: 13, fontWeight: 600, color: C.muted, textDecoration: \"none\", padding: \"8px 14px\", borderRadius: 8 }}>\n            Sign in\n          </Link>\n          <Link href=\"/auth/register\" style={{\n            fontSize: 13, fontWeight: 700, color: \"#fff\", textDecoration: \"none\",\n            padding: \"9px 18px\", borderRadius: 10,\n            background: C.navy,\n            boxShadow: \"0 4px 14px rgba(19,13,46,0.2)\",\n            display: \"flex\", alignItems: \"center\", gap: 6,\n          }}>\n            Start free <ArrowRight size={13}/>\n          </Link>\n        </div>\n\n        {/* Mobile hamburger */}\n        <button className=\"nav-mobile-btn\" onClick={() => setMobileOpen(!mobileOpen)}\n          style={{ display: \"none\", background: \"none\", border: \"none\", cursor: \"pointer\", color: C.navy, padding: 4 }}>\n          {mobileOpen ? <X size={22}/> : <Menu size={22}/>}\n        </button>\n      </nav>\n\n      {/* Mobile menu */}\n      <AnimatePresence>\n        {mobileOpen && (\n          <motion.div initial={{ opacity: 0, y: -10 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: -10 }}\n            style={{\n              position: \"fixed\", top: 64, left: 0, right: 0, zIndex: 99,\n              background: \"rgba(244,242,251,0.98)\", backdropFilter: \"blur(20px)\",\n              borderBottom: `1px solid ${C.border}`, padding: \"16px 24px 24px\",\n              display: \"flex\", flexDirection: \"column\", gap: 4,\n            }}>\n            {[\"Features\", \"Pricing\", \"How it works\"].map(l => (\n              <Link key={l} href={`/${l.toLowerCase().replace(/ /g, \"-\")}`}\n                onClick={() => setMobileOpen(false)}\n                style={{ fontSize: 15, fontWeight: 600, color: C.navy, textDecoration: \"none\", padding: \"12px 0\", borderBottom: `1px solid ${C.border}` }}>\n                {l}\n              </Link>\n            ))}\n            <Link href=\"/auth/register\" onClick={() => setMobileOpen(false)}\n              style={{ marginTop: 12, display: \"flex\", alignItems: \"center\", justifyContent: \"center\", gap: 6, padding: \"14px 0\", borderRadius: 12, background: C.navy, color: \"#fff\", textDecoration: \"none\", fontSize: 15, fontWeight: 700 }}>\n              Start free <ArrowRight size={14}/>\n            </Link>\n          </motion.div>\n        )}\n      </AnimatePresence>\n\n      <style>{`\n        @media(max-width:768px){ .nav-links,.nav-cta{display:none!important;} .nav-mobile-btn{display:flex!important;} }\n      `}</style>\n    </>\n  );\n}\n\n// ─── Hero ─────────────────────────────────────────────────────────────────────\nfunction Hero() {\n  const [email, setEmail] = useState(\"\");\n  const [submitted, setSubmitted] = useState(false);\n  const [loading, setLoading] = useState(false);\n\n  const join = async () => {\n    if (!email || loading) return;\n    setLoading(true);\n    try {\n      await fetch(`${API}/waitlist`, {\n        method: \"POST\", headers: { \"Content-Type\": \"application/json\" },\n        body: JSON.stringify({ email, source: \"homepage\" }),\n      });\n    } catch {}\n    setSubmitted(true);\n    setLoading(false);\n  };\n\n  return (\n    <section style={{\n      minHeight: \"100vh\",\n      display: \"flex\", flexDirection: \"column\", alignItems: \"center\", justifyContent: \"center\",\n      padding: \"120px 24px 80px\",\n      textAlign: \"center\",\n      position: \"relative\",\n      overflow: \"hidden\",\n    }}>\n      {/* Ambient background */}\n      <div style={{\n        position: \"absolute\", top: \"10%\", left: \"50%\", transform: \"translateX(-50%)\",\n        width: 700, height: 700, borderRadius: \"50%\",\n        background: \"radial-gradient(circle, rgba(107,53,232,0.08) 0%, transparent 65%)\",\n        filter: \"blur(60px)\", pointerEvents: \"none\",\n      }}/>\n\n      {/* Badge */}\n      <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.5 }}\n        style={{\n          display: \"inline-flex\", alignItems: \"center\", gap: 8,\n          padding: \"6px 14px 6px 6px\", borderRadius: 99,\n          background: \"#fff\", border: `1px solid ${C.border}`,\n          marginBottom: 28, boxShadow: \"0 2px 12px rgba(107,53,232,0.08)\",\n        }}>\n        <span style={{\n          fontSize: 10, fontWeight: 800, letterSpacing: \"0.08em\",\n          background: C.navy, color: \"#fff\",\n          padding: \"3px 8px\", borderRadius: 99,\n        }}>NEW</span>\n        <span style={{ fontSize: 12, color: C.muted, fontWeight: 500 }}>\n          KIRO AI now has 22 smart commands\n        </span>\n        <ChevronRight size={12} style={{ color: C.muted }}/>\n      </motion.div>\n\n      {/* Headline */}\n      <motion.h1 initial={{ opacity: 0, y: 16 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.6, delay: 0.1 }}\n        style={{\n          fontFamily: \"'Fraunces', Georgia, serif\",\n          fontSize: \"clamp(40px, 7vw, 76px)\",\n          fontWeight: 500, letterSpacing: \"-0.04em\",\n          color: C.navy, lineHeight: 1.04,\n          maxWidth: 800, margin: \"0 0 20px\",\n        }}>\n        The smarter way<br/>\n        <em style={{ fontStyle: \"italic\", color: C.purple }}>to dropship.</em>\n      </motion.h1>\n\n      {/* Subheading */}\n      <motion.p initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.6, delay: 0.2 }}\n        style={{ fontSize: \"clamp(15px, 2.5vw, 18px)\", color: C.muted, maxWidth: 520, lineHeight: 1.6, marginBottom: 40 }}>\n        Launch your store in 60 seconds. Import from any supplier worldwide.\n        Let KIRO handle the copy, pricing, and sales — so you focus on growing.\n      </motion.p>\n\n      {/* CTA */}\n      <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.5, delay: 0.3 }}\n        style={{ display: \"flex\", gap: 10, flexWrap: \"wrap\", justifyContent: \"center\" }}>\n        <Link href=\"/auth/register\" style={{\n          display: \"flex\", alignItems: \"center\", gap: 8,\n          padding: \"15px 28px\", borderRadius: 14,\n          background: C.navy, color: \"#fff\",\n          textDecoration: \"none\", fontSize: 15, fontWeight: 700,\n          boxShadow: \"0 8px 28px rgba(19,13,46,0.22)\",\n          letterSpacing: \"-0.01em\",\n          transition: \"all 0.15s\",\n        }}\n        onMouseEnter={e => { e.currentTarget.style.transform = \"translateY(-2px)\"; e.currentTarget.style.boxShadow = \"0 12px 36px rgba(19,13,46,0.3)\"; }}\n        onMouseLeave={e => { e.currentTarget.style.transform = \"translateY(0)\"; e.currentTarget.style.boxShadow = \"0 8px 28px rgba(19,13,46,0.22)\"; }}>\n          Start for free <ArrowRight size={15}/>\n        </Link>\n        <Link href=\"/auth/login\" style={{\n          display: \"flex\", alignItems: \"center\", gap: 8,\n          padding: \"15px 28px\", borderRadius: 14,\n          background: \"#fff\", color: C.navy,\n          textDecoration: \"none\", fontSize: 15, fontWeight: 600,\n          border: `1px solid ${C.border}`,\n          boxShadow: \"0 2px 12px rgba(107,53,232,0.06)\",\n          transition: \"all 0.15s\",\n        }}>\n          Sign in\n        </Link>\n      </motion.div>\n\n      {/* Trust signals */}\n      <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ delay: 0.5 }}\n        style={{ display: \"flex\", flexWrap: \"wrap\", alignItems: \"center\", justifyContent: \"center\", gap: \"8px 24px\", marginTop: 36 }}>\n        {[\n          \"No credit card required\",\n          \"Free plan available\",\n          \"Launch in 60 seconds\",\n          \"Cancel anytime\",\n        ].map(f => (\n          <span key={f} style={{ display: \"flex\", alignItems: \"center\", gap: 6, fontSize: 12, color: C.muted }}>\n            <Check size={11} color={C.purple} strokeWidth={2.5}/>\n            {f}\n          </span>\n        ))}\n      </motion.div>\n\n      {/* Dashboard preview */}\n      <motion.div initial={{ opacity: 0, y: 40 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.8, delay: 0.4 }}\n        style={{ width: \"100%\", maxWidth: 960, marginTop: 72, position: \"relative\" }}>\n        {/* Glow under the preview */}\n        <div style={{\n          position: \"absolute\", bottom: -40, left: \"10%\", right: \"10%\",\n          height: 80, borderRadius: \"50%\",\n          background: \"radial-gradient(ellipse, rgba(107,53,232,0.15), transparent)\",\n          filter: \"blur(20px)\",\n        }}/>\n        <div style={{\n          borderRadius: 20, overflow: \"hidden\",\n          border: `1px solid ${C.border}`,\n          boxShadow: \"0 32px 80px rgba(19,13,46,0.12), 0 2px 4px rgba(19,13,46,0.04)\",\n          background: \"#fff\",\n          position: \"relative\",\n        }}>\n          {/* Browser chrome */}\n          <div style={{\n            background: \"#F4F2FB\", padding: \"12px 16px\",\n            borderBottom: `1px solid ${C.border}`,\n            display: \"flex\", alignItems: \"center\", gap: 8,\n          }}>\n            <div style={{ display: \"flex\", gap: 5 }}>\n              {[\"#EF4444\",\"#F59E0B\",\"#10B981\"].map(c => (\n                <div key={c} style={{ width: 10, height: 10, borderRadius: \"50%\", background: c }}/>\n              ))}\n            </div>\n            <div style={{\n              flex: 1, maxWidth: 240, margin: \"0 auto\",\n              background: \"#fff\", borderRadius: 6, padding: \"4px 12px\",\n              fontSize: 11, color: C.muted, textAlign: \"center\", border: `1px solid ${C.border}`,\n            }}>\n              droposhq.com/dashboard\n            </div>\n          </div>\n          {/* Dashboard mock */}\n          <div style={{ background: \"#F4F2FB\", padding: 20, display: \"flex\", gap: 14, minHeight: 320 }}>\n            {/* Sidebar */}\n            <div style={{ width: 48, background: \"#fff\", borderRadius: 12, padding: \"16px 0\", display: \"flex\", flexDirection: \"column\", alignItems: \"center\", gap: 16, border: `1px solid ${C.border}` }}>\n              <div style={{ width: 28, height: 28, borderRadius: 8, background: \"linear-gradient(145deg,#2D1B69,#0D0625)\", display: \"flex\", alignItems: \"center\", justifyContent: \"center\" }}>\n                <svg width=\"11\" height=\"11\" viewBox=\"0 0 24 24\" fill=\"none\"><path d=\"M13 2L3 14h9l-1 8 10-12h-9z\" fill=\"white\"/></svg>\n              </div>\n              {[Zap, Package, ShoppingCart, BarChart3, Store].map((Icon, i) => (\n                <div key={i} style={{ width: 32, height: 32, borderRadius: 8, display: \"flex\", alignItems: \"center\", justifyContent: \"center\", background: i === 0 ? \"rgba(107,53,232,0.1)\" : \"transparent\" }}>\n                  <Icon size={14} color={i === 0 ? C.purple : \"rgba(19,13,46,0.3)\"}/>\n                </div>\n              ))}\n            </div>\n            {/* Content */}\n            <div style={{ flex: 1, display: \"flex\", flexDirection: \"column\", gap: 12 }}>\n              {/* Stats row */}\n              <div style={{ display: \"grid\", gridTemplateColumns: \"repeat(4,1fr)\", gap: 10 }}>\n                {[\n                  { label: \"Revenue\", value: \"₦284,000\", up: true },\n                  { label: \"Orders\",  value: \"42\",        up: true },\n                  { label: \"Products\",value: \"186\",       up: false },\n                  { label: \"Visitors\",value: \"1,240\",     up: true },\n                ].map(s => (\n                  <div key={s.label} style={{ background: \"#fff\", borderRadius: 12, padding: \"14px 12px\", border: `1px solid ${C.border}` }}>\n                    <p style={{ fontSize: 9, color: C.muted, margin: \"0 0 4px\", textTransform: \"uppercase\", letterSpacing: \"0.05em\" }}>{s.label}</p>\n                    <p style={{ fontSize: 17, fontWeight: 800, color: C.navy, margin: 0 }}>{s.value}</p>\n                    <p style={{ fontSize: 9, color: s.up ? \"#10B981\" : \"#EF4444\", margin: \"2px 0 0\" }}>{s.up ? \"↑\" : \"↓\"} this month</p>\n                  </div>\n                ))}\n              </div>\n              {/* KIRO chat */}\n              <div style={{ background: \"#fff\", borderRadius: 12, padding: 16, border: `1px solid ${C.border}`, flex: 1 }}>\n                <div style={{ display: \"flex\", alignItems: \"center\", gap: 8, marginBottom: 12 }}>\n                  <div style={{ width: 24, height: 24, borderRadius: 6, background: \"linear-gradient(145deg,#7c3aed,#4c1d95)\", display: \"flex\", alignItems: \"center\", justifyContent: \"center\" }}>\n                    <Zap size={11} color=\"#fff\"/>\n                  </div>\n                  <span style={{ fontSize: 11, fontWeight: 700, color: C.navy }}>KIRO</span>\n                  <span style={{ fontSize: 9, color: \"#10B981\", background: \"rgba(16,185,129,0.1)\", padding: \"2px 6px\", borderRadius: 99 }}>● Ready</span>\n                </div>\n                <div style={{ background: \"#F4F2FB\", borderRadius: 10, padding: \"10px 14px\", marginBottom: 8 }}>\n                  <p style={{ fontSize: 11, color: C.navy, margin: 0 }}>Your store made ₦47,000 this week. Want me to run a flash sale to hit ₦100k by Sunday?</p>\n                </div>\n                <div style={{ display: \"flex\", gap: 6 }}>\n                  {[\"Yes, let's go\", \"Show me the plan\", \"Not now\"].map(a => (\n                    <button key={a} style={{ fontSize: 9, padding: \"5px 10px\", borderRadius: 6, border: `1px solid ${C.border}`, background: \"#fff\", color: C.muted, cursor: \"pointer\", fontFamily: \"inherit\" }}>{a}</button>\n                  ))}\n                </div>\n              </div>\n            </div>\n          </div>\n        </div>\n      </motion.div>\n    </section>\n  );\n}\n\n// ─── Features ─────────────────────────────────────────────────────────────────\nconst FEATURES = [\n  {\n    icon: Sparkles,\n    color: \"#7C3AED\",\n    title: \"KIRO AI — your commerce brain\",\n    desc: \"Import products, write descriptions, run flash sales, recover abandoned carts, and get daily insights — all from a single chat.\",\n    tags: [\"22 slash commands\", \"Proactive alerts\", \"Daily brief\"],\n  },\n  {\n    icon: Store,\n    color: \"#0EA5E9\",\n    title: \"29 store templates\",\n    desc: \"From fashion to food to electronics — pick a template that matches your brand. Customize colors, fonts, and layout in seconds.\",\n    tags: [\"Fashion\", \"Beauty\", \"Electronics\", \"+26 more\"],\n  },\n  {\n    icon: Package,\n    color: \"#10B981\",\n    title: \"One-click supplier import\",\n    desc: \"Paste any AliExpress, Temu, or Amazon link. KIRO scrapes it, scores it A–F, and sets a margin price that actually makes you money.\",\n    tags: [\"AliExpress\", \"Temu\", \"Amazon\", \"CJDropshipping\"],\n  },\n  {\n    icon: TrendingUp,\n    color: \"#F59E0B\",\n    title: \"Paystack + Stripe payments\",\n    desc: \"Accept Naira payments via Paystack. Accept global card payments via Stripe. Both wired in — no code needed.\",\n    tags: [\"Card\", \"Bank transfer\", \"USSD\", \"International\"],\n  },\n  {\n    icon: BarChart3,\n    color: \"#EF4444\",\n    title: \"Smart analytics\",\n    desc: \"Revenue, orders, conversion rate, top products. KIRO reads your numbers and tells you what to do about them.\",\n    tags: [\"Revenue\", \"Conversion\", \"Products\", \"Customers\"],\n  },\n  {\n    icon: MessageSquare,\n    color: \"#8B5CF6\",\n    title: \"Opportunity engine\",\n    desc: \"KIRO scans your store every 6 hours for price wins, bundle opportunities, abandoned cart value, and seasonal moments.\",\n    tags: [\"Pricing AI\", \"Bundle detection\", \"Win-back\", \"Seasonal\"],\n  },\n];\n\nfunction Features() {\n  return (\n    <section id=\"features\" style={{ padding: \"100px 24px\", maxWidth: 1080, margin: \"0 auto\" }}>\n      <div style={{ textAlign: \"center\", marginBottom: 64 }}>\n        <p style={{ fontSize: 12, fontWeight: 700, letterSpacing: \"0.12em\", color: C.purple, marginBottom: 12, textTransform: \"uppercase\" }}>\n          EVERYTHING YOU NEED\n        </p>\n        <h2 style={{\n          fontFamily: \"'Fraunces', Georgia, serif\",\n          fontSize: \"clamp(32px, 5vw, 52px)\", fontWeight: 500, letterSpacing: \"-0.035em\",\n          color: C.navy, margin: \"0 0 16px\", lineHeight: 1.1,\n        }}>\n          Everything you need,<br/>\n          <em style={{ fontStyle: \"italic\", color: C.purple }}>nothing you don't.</em>\n        </h2>\n        <p style={{ fontSize: 16, color: C.muted, maxWidth: 480, margin: \"0 auto\", lineHeight: 1.6 }}>\n          Every feature is designed to help you sell more, work less, and grow faster.\n        </p>\n      </div>\n\n      <div style={{ display: \"grid\", gridTemplateColumns: \"repeat(3,1fr)\", gap: 16 }} className=\"feat-grid\">\n        {FEATURES.map((f, i) => {\n          const Icon = f.icon;\n          return (\n            <motion.div key={f.title}\n              initial={{ opacity: 0, y: 16 }} whileInView={{ opacity: 1, y: 0 }}\n              transition={{ delay: i * 0.08 }} viewport={{ once: true }}\n              style={{\n                background: \"#fff\", borderRadius: 20, padding: 24,\n                border: `1px solid ${C.border}`,\n                boxShadow: \"0 2px 12px rgba(107,53,232,0.05)\",\n                transition: \"all 0.2s\",\n              }}\n              whileHover={{ y: -4, boxShadow: \"0 8px 32px rgba(107,53,232,0.1)\" }}>\n              <div style={{\n                width: 44, height: 44, borderRadius: 12, marginBottom: 16,\n                background: `${f.color}12`,\n                display: \"flex\", alignItems: \"center\", justifyContent: \"center\",\n              }}>\n                <Icon size={20} color={f.color}/>\n              </div>\n              <h3 style={{ fontSize: 15, fontWeight: 700, color: C.navy, margin: \"0 0 8px\", letterSpacing: \"-0.02em\" }}>{f.title}</h3>\n              <p style={{ fontSize: 13, color: C.muted, lineHeight: 1.6, margin: \"0 0 16px\" }}>{f.desc}</p>\n              <div style={{ display: \"flex\", flexWrap: \"wrap\", gap: 6 }}>\n                {f.tags.map(t => (\n                  <span key={t} style={{ fontSize: 10, fontWeight: 600, padding: \"3px 9px\", borderRadius: 99, background: C.faint, color: C.purple, border: `1px solid ${C.border}` }}>\n                    {t}\n                  </span>\n                ))}\n              </div>\n            </motion.div>\n          );\n        })}\n      </div>\n\n      <style>{`@media(max-width:768px){ .feat-grid{grid-template-columns:1fr!important;} }`}</style>\n    </section>\n  );\n}\n\n// ─── Location-aware Pricing Preview ──────────────────────────────────────────\nconst PRICING_BY_REGION: Record<string, {\n  symbol: string; free: string; growth: string; pro: string;\n  period: string; tagline: string; badge?: string;\n}> = {\n  NG: { symbol:\"₦\", free:\"₦0\",     growth:\"₦9,500\",  pro:\"₦25,000\", period:\"/mo\", tagline:\"Pay in Naira. No forex stress.\", badge:\"🇳🇬 Nigerian prices\" },\n  GH: { symbol:\"₵\", free:\"₵0\",     growth:\"₵89\",     pro:\"₵240\",    period:\"/mo\", tagline:\"Priced for Ghana. Accept GHS payments.\", badge:\"🇬🇭 Ghana prices\" },\n  KE: { symbol:\"KSh\",free:\"KSh 0\", growth:\"KSh 1,300\",pro:\"KSh 3,500\",period:\"/mo\", tagline:\"Priced for Kenya. M-Pesa friendly.\", badge:\"🇰🇪 Kenya prices\" },\n  ZA: { symbol:\"R\",  free:\"R 0\",   growth:\"R 180\",   pro:\"R 470\",   period:\"/mo\", tagline:\"Priced for South Africa.\", badge:\"🇿🇦 South Africa prices\" },\n  GB: { symbol:\"£\",  free:\"£0\",    growth:\"£5\",      pro:\"£14\",     period:\"/mo\", tagline:\"Priced for the UK. Accept GBP.\", badge:\"🇬🇧 UK prices\" },\n  US: { symbol:\"$\",  free:\"$0\",    growth:\"$6\",      pro:\"$16\",     period:\"/mo\", tagline:\"Accept USD payments globally.\", badge:\"🇺🇸 US prices\" },\n  DEFAULT: { symbol:\"$\", free:\"$0\", growth:\"$6\",     pro:\"$16\",     period:\"/mo\", tagline:\"Accept payments in 50+ currencies.\", },\n};\n\nfunction detectRegion(): string {\n  if (typeof window === \"undefined\") return \"DEFAULT\";\n  try {\n    const tz = Intl.DateTimeFormat().resolvedOptions().timeZone;\n    if (tz.includes(\"Lagos\") || tz.includes(\"Abuja\")) return \"NG\";\n    if (tz.includes(\"Accra\")) return \"GH\";\n    if (tz.includes(\"Nairobi\")) return \"KE\";\n    if (tz.includes(\"Johannesburg\") || tz.includes(\"Cape_Town\")) return \"ZA\";\n    if (tz.includes(\"London\")) return \"GB\";\n    if (tz.includes(\"New_York\") || tz.includes(\"Los_Angeles\") || tz.includes(\"Chicago\")) return \"US\";\n    const lang = navigator.language || \"\";\n    if (lang.includes(\"en-NG\")) return \"NG\";\n    if (lang.includes(\"en-GH\")) return \"GH\";\n    if (lang.includes(\"en-KE\")) return \"KE\";\n    if (lang.includes(\"en-ZA\")) return \"ZA\";\n    if (lang.includes(\"en-GB\")) return \"GB\";\n    if (lang.includes(\"en-US\")) return \"US\";\n  } catch {}\n  return \"DEFAULT\";\n}\n\nfunction PricingPreview() {\n  const [region, setRegion] = useState(\"DEFAULT\");\n  useEffect(() => { setRegion(detectRegion()); }, []);\n  const p = PRICING_BY_REGION[region] || PRICING_BY_REGION.DEFAULT;\n\n  const plans = [\n    { name: \"Free\",   price: p.free,   features: [\"1 store\", \"20 products\", \"KIRO — 10 msg/day\", \"Basic analytics\"], highlight: false },\n    { name: \"Growth\", price: p.growth, features: [\"5 stores\", \"Unlimited products\", \"KIRO — unlimited\", \"Custom domain\", \"Priority support\"], highlight: true },\n    { name: \"Pro\",    price: p.pro,    features: [\"Unlimited stores\", \"Everything in Growth\", \"API access\", \"Dedicated support\"], highlight: false },\n  ];\n\n  return (\n    <section style={{ padding:\"80px 24px\", background:\"linear-gradient(160deg,#2D1B69 0%,#0D0625 100%)\" }}>\n      <div style={{ maxWidth:960, margin:\"0 auto\", textAlign:\"center\" }}>\n        <p style={{ fontSize:12, fontWeight:700, letterSpacing:\"0.12em\", color:\"rgba(196,181,253,0.7)\", marginBottom:12, textTransform:\"uppercase\" }}>PRICING</p>\n        <h2 style={{ fontFamily:\"'Fraunces',Georgia,serif\", fontSize:\"clamp(28px,5vw,48px)\", fontWeight:500, letterSpacing:\"-0.03em\", color:\"#fff\", margin:\"0 0 10px\", lineHeight:1.1 }}>\n          Start free.<br/>\n          <em style={{ fontStyle:\"italic\", color:\"#C4B5FD\" }}>Scale when you're ready.</em>\n        </h2>\n\n        {/* Location badge */}\n        {p.badge && (\n          <div style={{ display:\"inline-flex\", alignItems:\"center\", gap:6, margin:\"14px 0 32px\", padding:\"6px 14px\", borderRadius:99, background:\"rgba(255,255,255,0.08)\", border:\"1px solid rgba(255,255,255,0.12)\" }}>\n            <span style={{ fontSize:12, color:\"rgba(255,255,255,0.7)\", fontWeight:500 }}>{p.badge}</span>\n            <span style={{ fontSize:11, color:\"rgba(196,181,253,0.6)\" }}>· {p.tagline}</span>\n          </div>\n        )}\n        {!p.badge && <p style={{ fontSize:14, color:\"rgba(255,255,255,0.5)\", marginBottom:36 }}>{p.tagline}</p>}\n\n        <div style={{ display:\"grid\", gridTemplateColumns:\"repeat(3,1fr)\", gap:14, marginBottom:36 }} className=\"price-grid\">\n          {plans.map(plan => (\n            <div key={plan.name} style={{\n              background: plan.highlight ? \"rgba(255,255,255,0.1)\" : \"rgba(255,255,255,0.04)\",\n              borderRadius:20, padding:\"28px 24px\",\n              border: plan.highlight ? \"1px solid rgba(196,181,253,0.35)\" : \"1px solid rgba(255,255,255,0.08)\",\n              position:\"relative\",\n            }}>\n              {plan.highlight && (\n                <div style={{ position:\"absolute\", top:-12, left:\"50%\", transform:\"translateX(-50%)\", background:\"#C4B5FD\", color:\"#130D2E\", fontSize:10, fontWeight:800, padding:\"4px 14px\", borderRadius:99, letterSpacing:\"0.06em\", whiteSpace:\"nowrap\" }}>\n                  MOST POPULAR\n                </div>\n              )}\n              <p style={{ fontSize:13, fontWeight:700, color:\"rgba(196,181,253,0.8)\", margin:\"0 0 8px\" }}>{plan.name}</p>\n              <div style={{ display:\"flex\", alignItems:\"baseline\", gap:4, marginBottom:20 }}>\n                <span style={{ fontSize:30, fontWeight:900, color:\"#fff\", letterSpacing:\"-0.03em\" }}>{plan.price}</span>\n                <span style={{ fontSize:12, color:\"rgba(255,255,255,0.4)\" }}>{p.period}</span>\n              </div>\n              {plan.features.map(f => (\n                <div key={f} style={{ display:\"flex\", alignItems:\"center\", gap:8, marginBottom:10 }}>\n                  <Check size={11} color=\"#A78BFA\" strokeWidth={2.5}/>\n                  <span style={{ fontSize:12, color:\"rgba(255,255,255,0.65)\" }}>{f}</span>\n                </div>\n              ))}\n            </div>\n          ))}\n        </div>\n\n        <p style={{ fontSize:11, color:\"rgba(255,255,255,0.3)\", marginBottom:24 }}>\n          2% transaction fee on all plans · Cancel anytime\n        </p>\n        <Link href=\"/auth/register\" style={{ display:\"inline-flex\", alignItems:\"center\", gap:8, padding:\"14px 32px\", borderRadius:14, background:\"#fff\", color:C.navy, textDecoration:\"none\", fontSize:14, fontWeight:700, boxShadow:\"0 8px 24px rgba(0,0,0,0.2)\" }}>\n          Start for free <ArrowRight size={14}/>\n        </Link>\n      </div>\n      <style>{`@media(max-width:768px){ .price-grid{grid-template-columns:1fr!important;} }`}</style>\n    </section>\n  );\n}\n\n// ─── Social Proof ──────────────────────────────────────────────────────────────\nfunction SocialProof() {\n  const stats = [\n    { value: \"29\",   label: \"Store templates\" },\n    { value: \"60s\",  label: \"To launch a store\" },\n    { value: \"54+\",  label: \"Backend features\" },\n    { value: \"100%\", label: \"Uptime SLA\" },\n  ];\n\n  return (\n    <section style={{ padding: \"80px 24px\", maxWidth: 960, margin: \"0 auto\" }}>\n      <div style={{ display: \"grid\", gridTemplateColumns: \"repeat(4,1fr)\", gap: 24, textAlign: \"center\" }} className=\"stats-grid\">\n        {stats.map((s, i) => (\n          <motion.div key={s.label}\n            initial={{ opacity: 0, y: 12 }} whileInView={{ opacity: 1, y: 0 }}\n            transition={{ delay: i * 0.1 }} viewport={{ once: true }}>\n            <p style={{\n              fontFamily: \"'Fraunces', Georgia, serif\",\n              fontSize: \"clamp(36px, 6vw, 56px)\", fontWeight: 500,\n              color: C.navy, margin: \"0 0 6px\", letterSpacing: \"-0.04em\",\n              lineHeight: 1,\n            }}>{s.value}</p>\n            <p style={{ fontSize: 13, color: C.muted, margin: 0 }}>{s.label}</p>\n          </motion.div>\n        ))}\n      </div>\n      <style>{`@media(max-width:768px){ .stats-grid{grid-template-columns:1fr 1fr!important; gap:32px!important;} }`}</style>\n    </section>\n  );\n}\n\n// ─── CTA ──────────────────────────────────────────────────────────────────────\nfunction FinalCTA() {\n  return (\n    <section style={{ padding: \"100px 24px\", textAlign: \"center\" }}>\n      <motion.div initial={{ opacity: 0, y: 20 }} whileInView={{ opacity: 1, y: 0 }} viewport={{ once: true }}>\n        <h2 style={{\n          fontFamily: \"'Fraunces', Georgia, serif\",\n          fontSize: \"clamp(32px, 6vw, 60px)\", fontWeight: 500, letterSpacing: \"-0.04em\",\n          color: C.navy, margin: \"0 0 18px\", lineHeight: 1.08,\n        }}>\n          Your store is<br/>\n          <em style={{ fontStyle: \"italic\", color: C.purple }}>60 seconds away.</em>\n        </h2>\n        <p style={{ fontSize: 16, color: C.muted, maxWidth: 400, margin: \"0 auto 40px\", lineHeight: 1.6 }}>\n          No inventory. No coding. Just KIRO and a product idea.\n          The rest takes care of itself.\n        </p>\n        <Link href=\"/auth/register\" style={{\n          display: \"inline-flex\", alignItems: \"center\", gap: 10,\n          padding: \"16px 36px\", borderRadius: 16,\n          background: C.navy, color: \"#fff\",\n          textDecoration: \"none\", fontSize: 16, fontWeight: 700,\n          boxShadow: \"0 8px 32px rgba(19,13,46,0.2)\",\n          letterSpacing: \"-0.01em\",\n        }}\n        onMouseEnter={e => { e.currentTarget.style.transform = \"translateY(-2px)\"; }}\n        onMouseLeave={e => { e.currentTarget.style.transform = \"translateY(0)\"; }}>\n          Launch your store free <ArrowRight size={16}/>\n        </Link>\n        <p style={{ fontSize: 12, color: C.muted, marginTop: 16 }}>\n          No credit card · Free plan forever · Cancel anytime\n        </p>\n      </motion.div>\n    </section>\n  );\n}\n\n// ─── Footer ───────────────────────────────────────────────────────────────────\nfunction Footer() {\n  return (\n    <footer style={{\n      borderTop: `1px solid ${C.border}`, padding: \"40px 24px\",\n      background: \"#fff\",\n    }}>\n      <div style={{ maxWidth: 960, margin: \"0 auto\", display: \"flex\", flexWrap: \"wrap\", alignItems: \"center\", justifyContent: \"space-between\", gap: 16 }}>\n        <div style={{ display: \"flex\", alignItems: \"center\", gap: 10 }}>\n          <div style={{ width: 28, height: 28, borderRadius: 8, background: \"linear-gradient(145deg,#2D1B69,#0D0625)\", display: \"flex\", alignItems: \"center\", justifyContent: \"center\" }}>\n            <svg width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"none\"><path d=\"M13 2L3 14h9l-1 8 10-12h-9z\" fill=\"white\"/></svg>\n          </div>\n          <span style={{ fontSize: 14, fontWeight: 800, color: C.navy, letterSpacing: \"-0.02em\" }}>DropOS</span>\n          <span style={{ fontSize: 12, color: C.muted }}>© 2026</span>\n        </div>\n        <div style={{ display: \"flex\", gap: 20 }}>\n          {[\"Pricing\", \"Features\", \"Privacy\", \"Terms\"].map(l => (\n            <Link key={l} href={`/${l.toLowerCase()}`}\n              style={{ fontSize: 12, color: C.muted, textDecoration: \"none\", fontWeight: 500 }}>\n              {l}\n            </Link>\n          ))}\n        </div>\n      </div>\n    </footer>\n  );\n}\n\n// ─── Main ─────────────────────────────────────────────────────────────────────\nexport default function HomePage() {\n  return (\n    <div style={{ background: C.bg, fontFamily: \"'Plus Jakarta Sans', -apple-system, system-ui, sans-serif\", overflowX: \"hidden\" }}>\n      <style>{`\n        @import url('https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800;900&display=swap');\n        @import url('https://fonts.googleapis.com/css2?family=Fraunces:ital,wght@0,400;0,500;0,600;0,700;0,800;0,900;1,400;1,500;1,600;1,700;1,800;1,900&display=swap');\n        *{box-sizing:border-box;margin:0;padding:0;}\n        html{scroll-behavior:smooth;}\n      `}</style>\n      <Nav />\n      <Hero />\n      <SocialProof />\n      <Features />\n      <PricingPreview />\n      <FinalCTA />\n      <Footer />\n    </div>\n  );\n}\n"};
for(const[rel,c]of Object.entries(files)){const p=rel.split('/').join(path.sep);fs.mkdirSync(path.dirname(p),{recursive:true});fs.writeFileSync(p,c,'utf8');console.log('  ✓',rel.split('/').pop());}
